  return emailRegex.test(email) && email.length <= 254;
};

/**
 * Sanitize user output to prevent data leakage
 */
const sanitizeUser = (user) => ({
  id: user.id,
  name: sanitizeString(user.name),
  email: user.email, // In production, consider masking or omitting email
});

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint
 * GET /users
 * Query params:
 * - id: Filter by user ID (must be a positive integer)
 * - limit: Maximum number of users to return (1-100)
 */
app.get(
  '/users',
  [
    // Validate query parameters
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter by ID if provided
      let filteredUsers = users;
      if (req.query.id) {
        filteredUsers = users.filter(user => user.id === req.query.id);

        // Return 404 if user not found
        if (filteredUsers.length === 0) {
          return res.status(404).json({
            error: 'Not Found',
            message: `User with ID ${req.query.id} not found`,
          });
        }
      }

      // Apply limit if provided
      if (req.query.limit) {
        filteredUsers = filteredUsers.slice(0, req.query.limit);
      }

      // Sanitize output
      const sanitizedUsers = filteredUsers.map(sanitizeUser);

      res.json(sanitizedUsers);
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// SERVER CONFIGURATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close((err) => {
    if (err) {
      console.error('Error closing server:', err);
      process.exit(1);
    }
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

