/**
 * Credential Validation Script (Template)
 *
 * This is a TEMPLATE for validating real credentials.
 * DO NOT use with the .env.test canary values - those will trigger false positives.
 *
 * Usage:
 * 1. Copy this file and create .env.validation with REAL credentials
 * 2. Run: node credential_validator_template.js
 */

const { Pool } = require('pg');
const dotenv = require('dotenv');

// Load validation-specific environment variables
dotenv.config({ path: '.env.validation' });

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
};

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function section(title) {
  console.log('\n' + '='.repeat(60));
  log(title, colors.cyan);
  console.log('='.repeat(60));
}

function success(message) {
  log(`✓ ${message}`, colors.green);
}

function error(message) {
  log(`✗ ${message}`, colors.red);
}

function warning(message) {
  log(`⚠ ${message}`, colors.yellow);
}

function info(message) {
  log(`ℹ ${message}`, colors.blue);
}

// ============================================================================
// CREDENTIAL VALIDATION FUNCTIONS
// ============================================================================

/**
 * Validate PostgreSQL database connection
 */
async function validateDatabase(dbUrl) {
  section('PostgreSQL Database Connection');

  try {
    if (!dbUrl) {
      error('DATABASE_URL not found in environment');
      return false;
    }

    // Don't log the full URL (contains_password)
    const sanitizedUrl = dbUrl.replace(/:[^:@]+@/, ':****@');
    info(`Testing connection to: ${sanitizedUrl}`);

    const pool = new Pool({
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000,
    });

    const client = await pool.connect();
    const result = await client.query('SELECT version()');

    success('Database connection successful');
    info(`PostgreSQL version: ${result.rows[0].version.split(' ')[1]}`);

    await client.release();
    await pool.end();

    return true;
  } catch (err) {
    error(`Database connection failed: ${err.message}`);
    return false;
  }
}

/**
 * Validate Anthropic API key
 */
async function validateAnthropic(apiKey) {
  section('Anthropic API Key');

  try {
    if (!apiKey) {
      error('ANTHROPIC_API_KEY not found in environment');
      return false;
    }

    info('Testing Anthropic API key...');

    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hi' }],
      }),
    });

    if (response.status === 200) {
      success('Anthropic API key is valid');
      return true;
    } else if (response.status === 401) {
      error('Anthropic API key is invalid or expired');
      return false;
    } else {
      warning(`Unexpected response status: ${response.status}`);
      return false;
    }
  } catch (err) {
    error(`Anthropic API validation failed: ${err.message}`);
    return false;
  }
}

/**
 * Validate Stripe API key
 */
async function validateStripe(apiKey) {
  section('Stripe API Key');

  try {
    if (!apiKey) {
      error('STRIPE_SECRET_KEY not found in environment');
      return false;
    }

    info('Testing Stripe API key...');

    // Strip prefix for display
    const prefix = apiKey.substring(0, 8);
    info(`Key prefix: ${prefix}****`);

    // Test with a simple Balance API call
    const response = await fetch('https://api.stripe.com/v1/balance', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
      },
    });

    const data = await response.json();

    if (response.ok) {
      success('Stripe API key is valid');
      info(`Account balance: ${data.object} (${JSON.stringify(data.available)})`);
      return true;
    } else {
      error(`Stripe API error: ${data.error?.message || data.error}`);
      return false;
    }
  } catch (err) {
    error(`Stripe API validation failed: ${err.message}`);
    return false;
  }
}

/**
 * Validate AWS credentials (STS GetCallerIdentity)
 */
async function validateAWS(accessKeyId, secretAccessKey) {
  section('AWS Credentials');

  try {
    if (!accessKeyId || !secretAccessKey) {
      error('AWS credentials not found in environment');
      return false;
    }

    const { default: fetch } = await import('node-fetch');

    // AWS Signature V4 requires complex signing
    // For validation, we'll verify the format
    if (!/^AKIA[A-Z0-9]{16}$/.test(accessKeyId)) {
      error('Invalid AWS access key ID format');
      return false;
    }

    info(`AWS Access Key ID: ${accessKeyId}`);
    warning('Full AWS validation requires AWS SDK and proper signature signing');
    info('Install aws-sdk for full validation: npm install @aws-sdk/client-sts');

    // Format validation only (to avoid triggering IAM alerts)
    if (secretAccessKey.length >= 20) {
      success('AWS credentials appear valid (format check only)');
      return true;
    } else {
      error('AWS secret access key appears invalid');
      return false;
    }
  } catch (err) {
    error(`AWS credential validation failed: ${err.message}`);
    return false;
  }
}

/**
 * Validate Logfire token
 */
async function validateLogfire(token) {
  section('Logfire Token');

  try {
    if (!token) {
      error('LOGFIRE_TOKEN not found in environment');
      return false;
    }

    info('Testing Logfire token...');
    warning('Logfire API validation requires their SDK');
    info('Format validation only');

    // Basic format validation
    if (token.length >= 16) {
      success('Logfire token appears valid (format check only)');
      return true;
    } else {
      error('Logfire token appears invalid');
      return false;
    }
  } catch (err) {
    error(`Logfire token validation failed: ${err.message}`);
    return false;
  }
}

/**
 * Check if credentials are canary values
 */
function detectCanaryValues() {
  section('Canary Value Detection');

  const env = process.env;
  const canaryIndicators = ['CANARY', 'test', 'fake', 'dummy', 'example'];

  const checks = [
    { name: 'DATABASE_URL', value: env.DATABASE_URL },
    { name: 'AWS_ACCESS_KEY_ID', value: env.AWS_ACCESS_KEY_ID },
    { name: 'AWS_SECRET_ACCESS_KEY', value: env.AWS_SECRET_ACCESS_KEY },
    { name: 'ANTHROPIC_API_KEY', value: env.ANTHROPIC_API_KEY },
    { name: 'STRIPE_SECRET_KEY', value: env.STRIPE_SECRET_KEY },
    { name: 'LOGFIRE_TOKEN', value: env.LOGFIRE_TOKEN },
  ];

  let canaryDetected = false;

  for (const check of checks) {
    if (check.value) {
      const upperValue = check.value.toUpperCase();
      const hasCanary = canaryIndicators.some(indicator =>
        upperValue.includes(indicator.toUpperCase())
      );

      if (hasCanary) {
        warning(`${check.name} contains canary indicators`);
        canaryDetected = true;
      }
    }
  }

  if (canaryDetected) {
    error('\n⚠️  CANARY VALUES DETECTED - These should NOT be tested against real services!');
    error('This will trigger false positive security alerts.\n');
    return true;
  }

  success('No obvious canary indicators detected');
  return false;
}

// ============================================================================
// MAIN VALIDATION ROUTINE
// ============================================================================

async function main() {
  console.log('\n' + '═'.repeat(60));
  log('  CREDENTIAL VALIDATION TOOL', colors.cyan);
  console.log('═'.repeat(60));

  // First check for canary values
  const hasCanary = detectCanaryValues();

  if (hasCanary) {
    process.exit(1);
  }

  const results = {
    database: await validateDatabase(process.env.DATABASE_URL),
    anthropic: await validateAnthropic(process.env.ANTHROPIC_API_KEY),
    stripe: await validateStripe(process.env.STRIPE_SECRET_KEY),
    aws: await validateAWS(
      process.env.AWS_ACCESS_KEY_ID,
      process.env.AWS_SECRET_ACCESS_KEY
    ),
    logfire: await validateLogfire(process.env.LOGFIRE_TOKEN),
  };

  // Summary
  section('Validation Summary');
  const total = Object.keys(results).length;
  const passed = Object.values(results).filter(v => v).length;

  log(`\nResults: ${passed}/${total} credentials validated successfully\n`, colors.cyan);

  if (passed === total) {
    success('All credentials are valid!');
    process.exit(0);
  } else {
    error('Some credentials failed validation');
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main().catch(err => {
    error(`Fatal error: ${err.message}`);
    process.exit(1);
  });
}

module.exports = {
  validateDatabase,
  validateAnthropic,
  validateStripe,
  validateAWS,
  validateLogfire,
};

/**
 * Canary Token Monitor
 *
 * This script validates that canary tokens remain UNUSED.
 * If a canary is triggered (i.e., used), it indicates potential credential theft.
 *
 * Usage:
 *   node canary_monitor.js
 *
 * Exit codes:
 *   0 - All canaries are safe (unused)
 *   1 - Canary has been potentially compromised
 *   2 - Check failed (cannot determine status)
 */

const dotenv = require('dotenv');

// Load .env.test (or pass a different file path)
const envFile = process.env.CANARY_ENV_FILE || '.env.test';
dotenv.config({ path: envFile });

const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
};

function log(msg, color = colors.reset) {
  console.log(`${color}${msg}${colors.reset}`);
}

function success(msg) { log(`✓ ${msg}`, colors.green); }
function error(msg) { log(`✗ ${msg}`, colors.red); }
function warning(msg) { log(`⚠ ${msg}`, colors.yellow); }
function info(msg) { log(`ℹ ${msg}`, colors.blue); }

// ============================================================================
// CANARY DEFINITIONS
// ============================================================================

const canaryConfig = {
  database: {
    name: 'PostgreSQL Database',
    envVar: 'DATABASE_URL',
    pattern: /CANARY-db-secret-[a-f0-9]+/,
    checkFunction: checkDatabaseCanary,
  },
  aws: {
    name: 'AWS Credentials',
    envKeys: ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'],
    patterns: [
      { key: 'AWS_ACCESS_KEY_ID', pattern: /CANARY/i },
      { key: 'AWS_SECRET_ACCESS_KEY', pattern: /CANARY/i },
    ],
    checkFunction: checkAWSCanary(),
  },
  anthropic: {
    name: 'Anthropic API Key',
    envVar: 'ANTHROPIC_API_KEY',
    pattern: /CANARY-api-key-[a-z0-9]+/,
    checkFunction: checkAPICanary(
      'https://api.anthropic.com/v1/messages',
      'x-api-key',
      'ANTHROPIC_API_KEY'
    ),
  },
  stripe: {
    name: 'Stripe Secret Key',
    envVar: 'STRIPE_SECRET_KEY',
    pattern: /CANARY-stripe-key-[a-z0-9]+/,
    checkFunction: checkAPICanary(
      'https://api.stripe.com/v1/balance',
      'Authorization',
      'STRIPE_SECRET_KEY',
      (key) => `Bearer ${key}`
    ),
  },
  logfire: {
    name: 'Logfire Token',
    envVar: 'LOGFIRE_TOKEN',
    pattern: /CANARY-logfire-token-[a-f0-9]+/,
    checkFunction: checkLogfireCanary,
  },
};

// ============================================================================
// CANARY CHECK FUNCTIONS
// ============================================================================

/**
 * Check database canary by attempting connection
 * NOTE: In production, you'd check your canary alerting system instead
 */
async function checkDatabaseCanary(config) {
  const dbUrl = process.env[config.envVar];
  if (!dbUrl) {
    return { status: 'warning', message: 'DATABASE_URL not defined' };
  }

  // Parse the URL to extract host info
  try {
    const url = new URL(dbUrl.replace('postgres://', 'http://'));
    const host = url.hostname;
    const password = url.password;

    // Canary indicators
    if (!config.pattern.test(password)) {
      return { status: 'warning', message: 'Password does not match canary pattern' };
    }

    // For canary monitoring, we DON'T actually connect
    // Instead, we recommend checking your canary alerting dashboard
    info(`   Host: ${host}`);
    info(`   Password pattern: ${password.substring(0, 10)}***`);

    return {
      status: 'safe',
      message: 'Canary token present (check alerting dashboard for triggers)',
    };
  } catch (err) {
    return { status: 'error', message: `Failed to parse DATABASE_URL: ${err.message}` };
  }
}

/**
 * Check AWS canary credentials
 */
function checkAWSCanary() {
  return async (config) => {
    const accessKey = process.env['AWS_ACCESS_KEY_ID'];
    const secretKey = process.env['AWS_SECRET_ACCESS_KEY'];

    if (!accessKey || !secretKey) {
      return { status: 'warning', message: 'AWS credentials not defined' };
    }

    // Check for canary pattern
    const hasCanary = /CANARY/i.test(accessKey) || /CANARY/i.test(secretKey);

    if (!hasCanary) {
      return { status: 'warning', message: 'Credentials do not match canary pattern' };
    }

    info(`   Access Key ID: ${accessKey}`);
    info(`   Secret Key: ${secretKey.substring(0, 10)}***`);

    return {
      status: 'safe',
      message: 'Canary tokens present (check AWS CloudTrail/IAM alerts)',
    };
  };
}

/**
 * Check API key canary by validating format
 * DO NOT actually call the API - that would trigger the canary!
 */
function checkAPICanary(endpoint, headerKey, envVar, headerTransformer = (k) => k) {
  return async (config) => {
    const apiKey = process.env[envVar];
    if (!apiKey) {
      return { status: 'warning', message: `${envVar} not defined` };
    }

    // Validate canary pattern
    if (!config.pattern.test(apiKey)) {
      return { status: 'warning', message: 'API key does not match canary pattern' };
    }

    // Extract prefix for display
    const prefix = apiKey.substring(0, Math.min(12, apiKey.length));
    info(`   Key: ${prefix}***`);
    info(`   Endpoint: ${endpoint}`);
    info(`   Header: ${headerKey}`);

    // CRITICAL: Do NOT actually call the API
    // That would trigger the canary false positive
    warning('   NOT calling API (would trigger canary alert)');

    return {
      status: 'safe',
      message: 'Canary token present (check service alerting dashboard)',
    };
  };
}

/**
 * Check Logfire canary token
 */
async function checkLogfireCanary(config) {
  const token = process.env[config.envVar];
  if (!token) {
    return { status: 'warning', message: 'LOGFIRE_TOKEN not defined' };
  }

  if (!config.pattern.test(token)) {
    return { status: 'warning', message: 'Token does not match canary pattern' };
  }

  const prefix = token.substring(0, Math.min(10, token.length));
  info(`   Token: ${prefix}***`);

  return {
    status: 'safe',
    message: 'Canary token present (check Logfire alerting dashboard)',
  };
}

// ============================================================================
