      if (result.status === 'safe') {
        success(result.message);
        results.push({ name: config.name, status: 'safe', message: result.message });
      } else if (result.status === 'warning') {
        warning(result.message);
        results.push({ name: config.name, status: 'warning', message: result.message });
        hasWarnings = true;
      } else {
        error(result.message);
        results.push({ name: config.name, status: 'error', message: result.message });
        allSafe = false;
      }
    } catch (err) {
      error(`Check failed: ${err.message}`);
      results.push({ name: config.name, status: 'error', message: err.message });
      allSafe = false;
    }
  }

  // Print summary
  console.log('\n' + '═'.repeat(60));
  log('  SUMMARY', colors.cyan);
  console.log('═'.repeat(60));

  const safe = results.filter(r => r.status === 'safe').length;
  const warnings = results.filter(r => r.status === 'warning').length;
  const errors = results.filter(r => r.status === 'error').length;

  console.log('\nResults:');
  success(`  Safe (canaries present): ${safe}`);
  warning(`  Warnings: ${warnings}`);
  error(`  Errors: ${errors}`);

  if (allSafe && !hasWarnings) {
    console.log('\n' + colors.green);
    console.log('╔════════════════════════════════════════════════════════╗');
    console.log('║         ALL CANARIES ARE INTACT AND MONITORING         ║');
    console.log('╚════════════════════════════════════════════════════════╝');
    console.log(colors.reset);
    console.log('\nRecommendations:');
    console.log('  • Keep canary tokens in code to detect credential theft');
