    console.log('╔════════════════════════════════════════════════════════╗');
    console.log('║     CANNOT CONFIRM CANARY STATUS - INVESTIGATE        ║');
    console.log('╚════════════════════════════════════════════════════════╝');
    console.log(colors.reset);
    console.log('\nImmediate actions:');
    console.log('  • Check your canary alerting dashboard');
    console.log('  • Review recent authentication logs');
    console.log('  • Consider rotating affected credentials\n');

    process.exit(2);
  }
}

// Export functions for testing
module.exports = {
  canaryConfig,
  checkDatabaseCanary,
  checkAPICanary,
  checkLogfireCanary,
  checkAWSCanary,
};

// Run if called directly
if (require.main === module) {
