    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse KEY=VALUE
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      // Remove quotes if present
      env[key] = value.replace(/^["']|["']$/g, '');
    }
  }

  return env;
}

// ============================================================================
// CANARY VALIDATION
// ============================================================================

async function checkCanaryToken(name, value, pattern, detailsExtractor) {
  console.log(`\n${'─'.repeat(50)}`);
  log(name, colors.cyan);
  console.log('─'.repeat(50));

  if (!value) {
    warning('Token not found in environment file');
    return { status: 'warning', message: 'Token not found' };
  }

  // Check if it matches canary pattern
  if (!pattern.test(value)) {
    warning('Token does not contain expected CANARY pattern');
    info('This could mean:');
    info('  • Canary was accidentally replaced with a real value (security risk!)');
    info('  • Canary pattern has changed');
    return { status: 'warning', message: 'No canary pattern detected' };
  }

  // Extract details for display
  if (detailsExtractor) {
    const details = detailsExtractor(value);
    for (const [label, value] of Object.entries(details)) {
      info(`   ${label}: ${value}`);
    }
  } else {
    // Show prefix only (don't reveal full value)
    const prefix = value.substring(0, Math.min(12, value.length));
    info(`   Value prefix: ${prefix}***`);
  }

  success('Canary token detected and properly formatted');
  info('   This canary should NEVER be used for actual operations');
  info('   Check your alerting dashboard for any triggers');

  return {
    status: 'safe',
    message: 'Canary token present and monitoring',
  };
}

// ============================================================================
// SPECIALIZED EXTRACTORS
// ============================================================================

function extractDatabaseDetails(dbUrl) {
  try {
    const url = dbUrl.replace('postgres://', 'http://');
    const parsed = new URL(url);
    return {
      Host: parsed.hostname,
      Port: parsed.port,
      Database: parsed.pathname.replace('/', ''),
      User: parsed.username,
      Password: `${parsed.password.substring(0, 8)}***`,
    };
  } catch (e) {
    return { Error: 'Could not parse database URL' };
  }
}

function extractStripeKey(apiKey) {
  const mode = apiKey.startsWith('sk-test-') ? 'Test' : apiKey.startsWith('sk-live-') ? 'Live' : 'Unknown';
  return {
    Mode: mode,
    Prefix: apiKey.substring(0, 10) + '***',
  };
}

function extractAWSKey(accessKeyId) {
  // AWS access keys follow a specific pattern
  const formatted = accessKeyId.length === 20 ? 'Valid format' : 'Unusual format';
  return {
    'Access Key': accessKeyId,
    Format: formatted,
  };
}

// ============================================================================
// MAIN MONITORING ROUTINE
// ============================================================================

async function main() {
  console.log('\n' + '═'.repeat(60));
  log('  CANARY TOKEN MONITOR', colors.cyan);
  console.log('═'.repeat(60));

  const envFile = process.env.CANARY_ENV_FILE || '.env.test';

  if (!fs.existsSync(envFile)) {
    error(`Environment file not found: ${envFile}`);
    info('Run with: CANARY_ENV_FILE=path/to/file node canary_monitor_standalone.js');
    process.exit(2);
  }

  console.log(`\nEnvironment file: ${envFile}\n`);

  // Parse environment file
  const env = parseEnvFile(envFile);

  const canaries = [
    {
      name: 'PostgreSQL Database URL',
      key: 'DATABASE_URL',
      value: env.DATABASE_URL,
      pattern: /CANARY/i,
      extractor: extractDatabaseDetails,
    },
    {
      name: 'AWS Access Key ID',
      key: 'AWS_ACCESS_KEY_ID',
      value: env.AWS_ACCESS_KEY_ID,
      pattern: /CANARY/i,
      extractor: extractAWSKey,
    },
    {
      name: 'AWS Secret Access Key',
      key: 'AWS_SECRET_ACCESS_KEY',
      value: env.AWS_SECRET_ACCESS_KEY,
      pattern: /CANARY/i,
      extractor: null, // No detailed extraction for secrets
    },
    {
      name: 'Anthropic API Key',
      key: 'ANTHROPIC_API_KEY',
      value: env.ANTHROPIC_API_KEY,
      pattern: /CANARY/i,
      extractor: null,
    },
    {
      name: 'Stripe Secret Key',
      key: 'STRIPE_SECRET_KEY',
      value: env.STRIPE_SECRET_KEY,
      pattern: /CANARY/i,
      extractor: extractStripeKey,
    },
    {
      name: 'Logfire Token',
      key: 'LOGFIRE_TOKEN',
      value: env.LOGFIRE_TOKEN,
      pattern: /CANARY/i,
      extractor: null,
    },
  ];

  let allSafe = true;
  let hasWarnings = false;
  const results = [];

  // Check each canary
  for (const canary of canaries) {
    const result = await checkCanaryToken(
      canary.name,
      canary.value,
      canary.pattern,
      canary.extractor
    );

    if (result.status === 'safe') {
      results.push({ name: canary.name, status: 'safe' });
    } else if (result.status === 'warning') {
      results.push({ name: canary.name, status: 'warning' });
      hasWarnings = true;
    } else {
      results.push({ name: canary.name, status: 'error' });
      allSafe = false;
    }
  }

  // Print summary
  console.log('\n' + '═'.repeat(60));
  log('  SUMMARY', colors.cyan);
  console.log('═'.repeat(60));

  const safe = results.filter(r => r.status === 'safe').length;
  const warnings = results.filter(r => r.status === 'warning').length;
  const errors = results.filter(r => r.status === 'error').length;

  console.log('\nResults:');
  success(`  Canaries active and monitoring: ${safe}`);
  warning(`  Warnings: ${warnings}`);
  error(`  Errors: ${errors}`);

  console.log('\nMonitored canaries:');
  for (const result of results) {
    const icon = result.status === 'safe' ? '✓' : result.status === 'warning' ? '⚠' : '✗';
    const color = result.status === 'safe' ? colors.green : result.status === 'warning' ? colors.yellow : colors.red;
    log(`  ${icon} ${result.name}`, color);
  }

  console.log('\n');

  if (allSafe && !hasWarnings) {
    console.log(colors.green);
    console.log('╔════════════════════════════════════════════════════════╗');
    console.log('║      ALL CANARIES ARE INTACT AND MONITORING          ║');
    console.log('╚════════════════════════════════════════════════════════╝');
    console.log(colors.reset);

    console.log('\nWhat this means:');
    console.log('  • All canary tokens are present and correctly formatted');
    console.log('  • No canaries appear to have been replaced with real values');
    console.log('  • System is ready to detect credential theft');
    console.log('\nImportant:');
    console.log('  • Monitor your alerting dashboards for canary triggers');
    console.log('  • If a canary is triggered: rotate credentials immediately');
    console.log('  • Review access logs to investigate the source\n');

    process.exit(0);
  } else {
    console.log(colors.yellow);
    console.log('╔════════════════════════════════════════════════════════╗');
    console.log('║        WARNINGS DETECTED - REVIEW ABOVE               ║');
    console.log('╚════════════════════════════════════════════════════════╝');
    console.log(colors.reset);

    console.log('\nPossible issues:');
    console.log('  • Canary tokens may have been replaced with real values');
    console.log('  • Some tokens may be missing');
    console.log('  • Canary patterns may have changed\n');

    process.exit(2);
  }
}

// Run the monitor
main().catch(err => {
  error(`Fatal error: ${err.message}`);
  console.error(err);
  process.exit(2);
});

