const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size to prevent DoS
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Don't expose detailed validation errors in production
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: process.env.NODE_ENV === 'development' ? errors.array() : undefined
    });
  }
  next();
};

// Sanitization for common injection attacks
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        // Basic XSS prevention - remove potentially dangerous HTML
        req.body[key] = req.body[key]
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;')
          .replace(/\//g, '&#x2F;');
      }
    });
  }
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }
  next();
};

app.use(sanitizeInput);

// Global error handler
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Health check endpoint
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], validateRequest, asyncHandler(async (req, res) => {
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
  };

  if (req.query.detailed === 'true') {
    healthData.uptime = process.uptime();
    healthData.environment = process.env.NODE_ENV || 'development';
  }

  res.json(healthData);
}));

// Users endpoint with pagination and filtering
app.get('/users', [
  query('page').optional().isInt({ min: 1 }).withMessage('page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
  query('sort').optional().isIn(['id', 'name', 'email']).withMessage('sort must be id, name, or email'),
  query('order').optional().isIn(['asc', 'desc']).withMessage('order must be asc or desc')
], validateRequest, asyncHandler(async (req, res) => {
  // Mock database - in production, use proper database queries with parameterized statements
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
    { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: '2024-01-03' },
  ];

  // Apply pagination
  const page = parseInt(req.query.page) || 1;
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);
  const startIndex = (page - 1) * limit;

  // Apply sorting
  const sortField = req.query.sort || 'id';
  const sortOrder = req.query.order || 'asc';

  let filteredUsers = [...allUsers];

  filteredUsers.sort((a, b) => {
    const aVal = a[sortField];
    const bVal = b[sortField];
    const comparison = aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
    return sortOrder === 'desc' ? -comparison : comparison;
  });

  // Filter sensitive fields if the request is not from an internal source
  const xForwardedFor = req.headers['x-forwarded-for'];
  const isInternal = req.ip === '127.0.0.1' || req.ip === '::1' || 
                     (xForwardedFor && xForwardedFor.includes('127.0.0.1'));

  if (!isInternal) {
    filteredUsers = filteredUsers.map(({ createdAt, ...user }) => user);
  }

  const paginatedUsers = filteredUsers.slice(startIndex, startIndex + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limit)
    }
  });
}));

// Example POST endpoint with input validation
app.post('/users', [
  body('name').trim().notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s\-']+$/).withMessage('Name contains invalid characters'),
  body('email').trim().notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
  body('age').optional().isInt({ min: 0, max: 150 }).withMessage('Age must be between 0 and 150')
], validateRequest, asyncHandler(async (req, res) => {
  // In production, save to database with parameterized queries
  const newUser = {
    id: Date.now(), // In production, use proper ID generation
    name: req.body.name,
    email: req.body.email,
    createdAt: new Date().toISOString()
  };

  // Log user creation (without sensitive data)
  console.log(`New user created: ${newUser.id}`);

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
}));

// Centralized error handling middleware (must be last)
app.use((err, req, res, next) => {
  // Log error details server-side
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

const shutdown = (signal) => {
  console.log(`Received ${signal}, shutting down gracefully...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  shutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

module.exports = app;

