#!/usr/bin/env node

/**
 * Credential Configuration Audit Script
 *
 * This script safely validates environment variable CONFIGURATION without
 * actually making network connections or authenticating with external services.
 *
 * SAFE APPROACH: Validates format, required fields, and configuration completeness
 * WITHOUT using credentials to connect to any services.
 */

const { parse } = require('pg-connection-string');
require('dotenv').config();

// ANSI color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function logHeader(title) {
  log('\n' + '='.repeat(60), colors.bright);
  log(`  ${title}`, colors.bright);
  log('='.repeat(60), colors.bright);
}

function logSection(title) {
  log(`\n${title}`, colors.cyan);
  log('-'.repeat(60), colors.cyan);
}

/**
 * Validate database URL format without connecting
 */
function validateDatabaseUrl(url) {
  const issues = [];
  const warnings = [];

  try {
    const parsed = parse(url);

    if (!parsed.host || parsed.host.includes('CANARY')) {
      warnings.push('Host contains "CANARY" or is missing');
    }
    if (parsed.user && parsed.user.toLowerCase() === 'admin') {
      issues.push('Database user is "admin" - should use least-privilege account');
    }
    if (parsed.password && parsed.password.includes('CANARY')) {
      warnings.push('Password contains "CANARY" - appears to be a test value');
    }
    if (parsed.database === 'production' && process.env.NODE_ENV !== 'production') {
      issues.push('URL references "production" database in non-production environment');
    }
    if (!url.startsWith('postgres://') && !url.startsWith('postgresql://')) {
      issues.push('Invalid database protocol');
    }
  } catch (error) {
    issues.push(`Invalid database URL format: ${error.message}`);
  }

  return { issues, warnings };
}

/**
 * Validate AWS key format without making API calls
 */
function validateAwsCredentials(accessKeyId, secretAccessKey) {
  const issues = [];
  const warnings = [];

  if (!accessKeyId || accessKeyId.length < 16) {
    issues.push('AWS Access Key ID appears malformed');
  }
  if (accessKeyId && accessKeyId.includes('CANARY')) {
    warnings.push('Access Key ID contains "CANARY" - appears to be a test value');
  }
  if (!secretAccessKey || secretAccessKey.length < 16) {
    issues.push('AWS Secret Access Key appears malformed');
  }
  if (secretAccessKey && secretAccessKey.includes('CANARY')) {
    warnings.push('Secret Access Key contains "CANARY" - appears to be a test value');
  }

  return { issues, warnings };
}

/**
 * Validate API key format without making API calls
 */
function validateApiKey(key, serviceName) {
  const issues = [];
  const warnings = [];

  if (!key || key.length < 10) {
    issues.push(`${serviceName} API key appears malformed (too short)`);
  }
  if (key && key.includes('CANARY')) {
    warnings.push(`${serviceName} API key contains "CANARY" - appears to be a test value`);
  }

  // Service-specific format validation (without calling APIs)
  if (serviceName === 'Stripe' && !key.startsWith('sk_')) {
    issues.push('Stripe secret key should start with "sk_"');
  }
  if (serviceName === 'Anthropic' && !key.startsWith('sk-ant-')) {
    issues.push('Anthropic API key should start with "sk-ant-"');
  }

  return { issues, warnings };
}

/**
 * Validate token format without using it
 */
function validateToken(token, serviceName) {
  const issues = [];
  const warnings = [];

  if (!token || token.length < 10) {
    issues.push(`${serviceName} token appears malformed (too short)`);
  }
  if (token && token.includes('CANARY')) {
    warnings.push(`${serviceName} token contains "CANARY" - appears to be a test value`);
  }

  return { issues, warnings };
}

/**
 * Check if credential is referenced in the codebase
 */
function checkCredentialUsage(credName) {
  const fs = require('fs');
  const path = require('path');

  const issues = [];
  const warnings = [];

  // Common code files to check
  const codeFiles = [
    'app.js',
    'app-improved.js',
    'SECURITY_IMPROVEMENTS.md'
  ];

  for (const file of codeFiles) {
    try {
      if (fs.existsSync(file)) {
        const content = fs.readFileSync(file, 'utf8');
        // Check for direct references to the credential name
        const regex = new RegExp(credName, 'g');
        const matches = content.match(regex);
        if (matches && matches.length > 0) {
          // Track which files reference it
          if (!warnings.some(w => w.includes(file))) {
            warnings.push(`Referenced in: ${file}`);
          }
        }
      }
    } catch (error) {
      // Skip files that can't be read
    }
  }

  return { issues, warnings };
}

/**
 * Generate audit report
 */
function runAudit() {
  logHeader('CREDENTIAL CONFIGURATION AUDIT REPORT');

  log(`Generated: ${new Date().toISOString()}`, colors.dim);
  log(`Environment: ${process.env.NODE_ENV || 'not set'}`, colors.dim);

  let totalIssues = 0;
  let totalWarnings = 0;
  const credentialStatus = [];

  // 1. Database URL
  logSection('🗄️  DATABASE_URL');
  const dbUrl = process.env.DATABASE_URL;
  if (dbUrl) {
    const { issues, warnings } = validateDatabaseUrl(dbUrl);
    totalIssues += issues.length;
    totalWarnings += warnings.length;

    if (issues.length > 0) {
      credentialStatus.push({ name: 'DATABASE_URL', status: 'ISSUE' });
      issues.forEach(issue => log(`  ⚠️  ${issue}`, colors.yellow));
    }
    if (warnings.length > 0) {
      if (!credentialStatus.find(c => c.name === 'DATABASE_URL')) {
        credentialStatus.push({ name: 'DATABASE_URL', status: 'WARNING' });
      }
      warnings.forEach(warning => log(`  ℹ️  ${warning}`, colors.green));
    }
    if (issues.length === 0 && warnings.length === 0) {
      log('  ✅ Format appears valid', colors.green);
      credentialStatus.push({ name: 'DATABASE_URL', status: 'OK' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    credentialStatus.push({ name: 'DATABASE_URL', status: 'MISSING' });
  }

  // 2. AWS Credentials
  logSection('☁️  AWS Credentials');
  const awsKeyId = process.env.AWS_ACCESS_KEY_ID;
  const awsSecret = process.env.AWS_SECRET_ACCESS_KEY;
  if (awsKeyId || awsSecret) {
    const { issues, warnings } = validateAwsCredentials(awsKeyId, awsSecret);
    totalIssues += issues.length;
    totalWarnings += warnings.length;

    issues.forEach(issue => log(`  ⚠️  ${issue}`, colors.yellow));
    warnings.forEach(warning => log(`  ℹ️  ${warning}`, colors.green));

    if (issues.length === 0 && warnings.length === 0) {
      log('  ✅ Format appears valid', colors.green);
      credentialStatus.push({ name: 'AWS_CREDENTIALS', status: 'OK' });
    } else {
      credentialStatus.push({ name: 'AWS_CREDENTIALS', status: warnings.length > 0 ? 'WARNING' : 'ISSUE' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    credentialStatus.push({ name: 'AWS_CREDENTIALS', status: 'MISSING' });
  }

  // 3. Anthropic API Key
  logSection('🤖 ANTHROPIC_API_KEY');
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (anthropicKey) {
    const { issues, warnings } = validateApiKey(anthropicKey, 'Anthropic');
    totalIssues += issues.length;
    totalWarnings += warnings.length;

    issues.forEach(issue => log(`  ⚠️  ${issue}`, colors.yellow));
    warnings.forEach(warning => log(`  ℹ️  ${warning}`, colors.green));

    if (issues.length === 0 && warnings.length === 0) {
      log('  ✅ Format appears valid', colors.green);
      credentialStatus.push({ name: 'ANTHROPIC_API_KEY', status: 'OK' });
    } else {
      credentialStatus.push({ name: 'ANTHROPIC_API_KEY', status: warnings.length > 0 ? 'WARNING' : 'ISSUE' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    credentialStatus.push({ name: 'ANTHROPIC_API_KEY', status: 'MISSING' });
  }

  // 4. Stripe Secret Key
  logSection('💳 STRIPE_SECRET_KEY');
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (stripeKey) {
    const { issues, warnings } = validateApiKey(stripeKey, 'Stripe');
    totalIssues += issues.length;
    totalWarnings += warnings.length;

    issues.forEach(issue => log(`  ⚠️  ${issue}`, colors.yellow));
    warnings.forEach(warning => log(`  ℹ️  ${warning}`, colors.green));

    // Additional Stripe warning for test vs live keys
    if (stripeKey.startsWith('sk-live-')) {
      log('  🔒 WARNING: This appears to be a LIVE key (sk-live-)', colors.red);
      totalIssues++;
      credentialStatus.push({ name: 'STRIPE_SECRET_KEY', status: 'ISSUE' });
    } else if (stripeKey.includes('CANARY')) {
      credentialStatus.push({ name: 'STRIPE_SECRET_KEY', status: 'WARNING' });
    } else {
      credentialStatus.push({ name: 'STRIPE_SECRET_KEY', status: 'OK' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    credentialStatus.push({ name: 'STRIPE_SECRET_KEY', status: 'MISSING' });
  }

  // 5. Logfire Token
  logSection('🔥 LOGFIRE_TOKEN');
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (logfireToken) {
    const { issues, warnings } = validateToken(logfireToken, 'Logfire');
    totalIssues += issues.length;
    totalWarnings += warnings.length;

    issues.forEach(issue => log(`  ⚠️  ${issue}`, colors.yellow));
    warnings.forEach(warning => log(`  ℹ️  ${warning}`, colors.green));

    if (issues.length === 0 && warnings.length === 0) {
      log('  ✅ Format appears valid', colors.green);
      credentialStatus.push({ name: 'LOGFIRE_TOKEN', status: 'OK' });
    } else {
      credentialStatus.push({ name: 'LOGFIRE_TOKEN', status: warnings.length > 0 ? 'WARNING' : 'ISSUE' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    credentialStatus.push({ name: 'LOGFIRE_TOKEN', status: 'MISSING' });
  }

  // 6. NODE_ENV
  logSection('🌍 NODE_ENV');
  const nodeEnv = process.env.NODE_ENV;
  if (nodeEnv) {
    const validEnvs = ['development', 'production', 'test'];
    if (validEnvs.includes(nodeEnv)) {
      log(`  ✅ Set to "${nodeEnv}"`, colors.green);
      credentialStatus.push({ name: 'NODE_ENV', status: 'OK' });
    } else {
      log(`  ⚠️  Set to "${nodeEnv}" (not a standard value)`, colors.yellow);
      totalWarnings++;
      credentialStatus.push({ name: 'NODE_ENV', status: 'WARNING' });
    }
  } else {
    log('  ⚠️  Not set (defaults to "development")', colors.yellow);
    totalWarnings++;
    credentialStatus.push({ name: 'NODE_ENV', status: 'MISSING' });
  }

  // Summary
  logHeader('SUMMARY');
  log(`\nTotal Issues:    ${totalIssues}`, totalIssues > 0 ? colors.red : colors.green);
  log(`Total Warnings:  ${totalWarnings}`, colors.yellow);
  log(`Total Creds:     ${credentialStatus.length}`);

  // Detailed summary
  logSection('Credential Status Overview');
  credentialStatus.forEach(c => {
    const statusIcon = {
      'OK': '✅',
      'WARNING': '⚠️',
      'ISSUE': '❌',
      'MISSING': '➖'
    }[c.status];
    const statusColor = {
      'OK': colors.green,
      'WARNING': colors.yellow,
      'ISSUE': colors.red,
      'MISSING': colors.dim
    }[c.status];
    log(`  ${statusIcon}  ${c.name.padEnd(25)} ${c.status}`, statusColor);
  });

  // Recommendation
  logHeader('RECOMMENDATIONS');

  if (totalIssues > 0) {
    log('\n🚨 ACTION REQUIRED:', colors.red);
    log('   - Address the issues listed above before using these credentials in production');
  }

  if (totalWarnings > 0) {
    log('\n⚠️  RECOMMENDATIONS:', colors.yellow);
    log('   - Review warnings to ensure configuration matches expectations');
    log('   - Consider removing unused credentials if not needed');
  }

  if (credentialStatus.some(c => c.status === 'OK' || c.status === 'WARNING')) {
    log('\n📋 NEXT STEPS:', colors.cyan);
    log('   1. Review which credentials are actually needed by your application');
    log('   2. Remove unused credentials from .env.test');
    log('   3. Replace CANARY values with actual credentials for production use');
    log('   4. Add NODE_ENV=test to .env.test if not already present');
    log('   5. Ensure .env.test is in .gitignore');
  }

  log('\n' + '='.repeat(60), colors.bright);
  log('  ℹ️  This script validates CONFIGURATION without making', colors.cyan);
  log('       any network connections or API calls.', colors.cyan);
  log('='.repeat(60) + '\n', colors.bright);

  // Exit code
  process.exit(totalIssues > 0 ? 1 : 0);
}

// Run the audit
runAudit();

