#!/usr/bin/env node

/**
 * Simple Credential Configuration Audit
 *
 * Validates environment variable CONFIGURATION without making network calls
 */

// ANSI colors
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  bright: '\x1b[1m',
  dim: '\x1b[2m',
};

function log(msg, color = colors.reset) {
  console.log(`${color}${msg}${colors.reset}`);
}

function logHeader(title) {
  log('\n' + '='.repeat(60), colors.bright);
  log(`  ${title}`, colors.bright);
  log('='.repeat(60), colors.bright);
}

function logSection(title) {
  log(`\n${title}`, colors.cyan);
  log('-'.repeat(60), colors.cyan);
}

// Simple database URL parser
function parseDatabaseUrl(url) {
  try {
    const match = url.match(/postgres(?:ql)?:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (match) {
      return {
        user: match[1],
        password: match[2],
        host: match[3],
        port: match[4],
        database: match[5]
      };
    }
    return null;
  } catch (e) {
    return null;
  }
}

// Read .env.test file manually
function loadEnvFile() {
  const fs = require('fs');
  const env = {};
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    content.split('\n').forEach(line => {
      const match = line.match(/^([^#]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();
        env[key] = value;
      }
    });
  } catch (e) {
    log('Warning: Could not read .env.test file', colors.yellow);
  }
  return env;
}

// Run audit
function runAudit() {
  logHeader('CREDENTIAL CONFIGURATION AUDIT');
  log('Safe audit - validates format WITHOUT making network connections\n', colors.dim);

  const env = loadEnvFile();
  let totalIssues = 0;
  let totalWarnings = 0;
  const results = [];

  // 1. DATABASE_URL
  logSection('🗄️  DATABASE_URL');
  const dbUrl = env.DATABASE_URL;
  if (dbUrl) {
    const parsed = parseDatabaseUrl(dbUrl);
    const warnings = [];
    const issues = [];

    log(`  URL: ${dbUrl.substring(0, 30)}...`, colors.dim);

    if (dbUrl.includes('CANARY')) {
      warnings.push('Contains "CANARY" - this is a synthetic test value');
    }
    if (parsed) {
      if (parsed.user === 'admin') {
        issues.push('Uses "admin" user - should use least-privilege account');
      }
      if (parsed.password.includes('CANARY')) {
        warnings.push('Password is a CANARY value - not a real credential');
      }
      if (parsed.database === 'production') {
        issues.push('References "production" database in test file');
      }
      if (parsed.host !== 'db.internal') {
        warnings.push(`Host is "${parsed.host}" - check if this is correct`);
      }
    }

    warnings.forEach(w => log(`  ℹ️  ${w}`, colors.green));
    issues.forEach(i => log(`  ⚠️  ${i}`, colors.yellow));

    if (issues.length > 0) {
      results.push({ name: 'DATABASE_URL', status: 'ISSUE' });
      totalIssues += issues.length;
    } else if (warnings.length > 0) {
      results.push({ name: 'DATABASE_URL', status: 'STALE/CANARY' });
      totalWarnings += warnings.length;
    } else {
      results.push({ name: 'DATABASE_URL', status: 'NEEDS_VALIDATION' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    results.push({ name: 'DATABASE_URL', status: 'MISSING' });
  }

  // 2. AWS_ACCESS_KEY_ID
  logSection('☁️  AWS_ACCESS_KEY_ID');
  const awsKey = env.AWS_ACCESS_KEY_ID;
  if (awsKey) {
    log(`  Key: ${awsKey.substring(0, 10)}...`, colors.dim);
    if (awsKey.includes('CANARY')) {
      log('  ℹ️  Contains "CANARY" - synthetic test value (NOT a real AWS key)', colors.green);
      results.push({ name: 'AWS_ACCESS_KEY_ID', status: 'STALE/CANARY' });
      totalWarnings++;
    } else if (awsKey.length < 16) {
      log('  ⚠️  Malformed - AWS keys are typically 20+ characters', colors.yellow);
      results.push({ name: 'AWS_ACCESS_KEY_ID', status: 'MALFORMED' });
      totalIssues++;
    } else {
      log('  ⚠️  Appears to be a real key - verify if intended', colors.yellow);
      results.push({ name: 'AWS_ACCESS_KEY_ID', status: 'NEEDS_VALIDATION' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    results.push({ name: 'AWS_ACCESS_KEY_ID', status: 'MISSING' });
  }

  // 3. AWS_SECRET_ACCESS_KEY
  logSection('☁️  AWS_SECRET_ACCESS_KEY');
  const awsSecret = env.AWS_SECRET_ACCESS_KEY;
  if (awsSecret) {
    log(`  Secret: ${awsSecret.substring(0, 10)}...`, colors.dim);
    if (awsSecret.includes('CANARY')) {
      log('  ℹ️  Contains "CANARY" - synthetic test value (NOT a real secret)', colors.green);
      results.push({ name: 'AWS_SECRET_ACCESS_KEY', status: 'STALE/CANARY' });
      totalWarnings++;
    } else if (awsSecret.length < 16) {
      log('  ⚠️  Malformed - AWS secrets are typically 40+ characters', colors.yellow);
      results.push({ name: 'AWS_SECRET_ACCESS_KEY', status: 'MALFORMED' });
      totalIssues++;
    } else {
      log('  🔒 Appears to be a real secret - verify if intended', colors.yellow);
      results.push({ name: 'AWS_SECRET_ACCESS_KEY', status: 'NEEDS_VALIDATION' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    results.push({ name: 'AWS_SECRET_ACCESS_KEY', status: 'MISSING' });
  }

  // 4. ANTHROPIC_API_KEY
  logSection('🤖 ANTHROPIC_API_KEY');
  const anthropicKey = env.ANTHROPIC_API_KEY;
  if (anthropicKey) {
    log(`  Key: ${anthropicKey.substring(0, 15)}...`, colors.dim);
    if (anthropicKey.includes('CANARY')) {
      log('  ℹ️  Contains "CANARY" - synthetic test value (NOT a real API key)', colors.green);
      results.push({ name: 'ANTHROPIC_API_KEY', status: 'STALE/CANARY' });
      totalWarnings++;
    } else if (!anthropicKey.startsWith('sk-ant-')) {
      log('  ⚠️  Wrong format - Anthropic keys start with "sk-ant-"', colors.yellow);
      results.push({ name: 'ANTHROPIC_API_KEY', status: 'MALFORMED' });
      totalIssues++;
    } else {
      log('  🤔 Format looks correct - verify if intended for use', colors.yellow);
      results.push({ name: 'ANTHROPIC_API_KEY', status: 'NEEDS_VALIDATION' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    results.push({ name: 'ANTHROPIC_API_KEY', status: 'MISSING' });
  }

  // 5. STRIPE_SECRET_KEY
  logSection('💳 STRIPE_SECRET_KEY');
  const stripeKey = env.STRIPE_SECRET_KEY;
  if (stripeKey) {
    log(`  Key: ${stripeKey.substring(0, 15)}...`, colors.dim);
    if (stripeKey.includes('CANARY')) {
      log('  ℹ️  Contains "CANARY" - synthetic test value (NOT a real key)', colors.green);
      results.push({ name: 'STRIPE_SECRET_KEY', status: 'STALE/CANARY' });
      totalWarnings++;
    } else if (stripeKey.startsWith('sk-live-')) {
      log('  🚨 This appears to be a REAL LIVE key - extremely sensitive!', colors.red);
      log('  ⚠️  Should not be in test environment', colors.yellow);
      results.push({ name: 'STRIPE_SECRET_KEY', status: 'SECURITY_RISK' });
      totalIssues++;
    } else if (stripeKey.startsWith('sk-test-')) {
      log('  ℹ️  This is a test key (sk-test-) - appropriate for testing', colors.green);
      results.push({ name: 'STRIPE_SECRET_KEY', status: 'TEST_KEY' });
    } else {
      log('  ⚠️  Unknown format - verify if correct', colors.yellow);
      results.push({ name: 'STRIPE_SECRET_KEY', status: 'NEEDS_VALIDATION' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    results.push({ name: 'STRIPE_SECRET_KEY', status: 'MISSING' });
  }

  // 6. LOGFIRE_TOKEN
  logSection('🔥 LOGFIRE_TOKEN');
  const logfireToken = env.LOGFIRE_TOKEN;
  if (logfireToken) {
    log(`  Token: ${logfireToken.substring(0, 10)}...`, colors.dim);
    if (logfireToken.includes('CANARY')) {
      log('  ℹ️  Contains "CANARY" - synthetic test value (NOT a real token)', colors.green);
      results.push({ name: 'LOGFIRE_TOKEN', status: 'STALE/CANARY' });
      totalWarnings++;
    } else {
      log('  🔒 Appears to be a real token - verify if intended', colors.yellow);
      results.push({ name: 'LOGFIRE_TOKEN', status: 'NEEDS_VALIDATION' });
    }
  } else {
    log('  ❌ Not configured', colors.red);
    results.push({ name: 'LOGFIRE_TOKEN', status: 'MISSING' });
  }

  // 7. NODE_ENV
  logSection('🌍 NODE_ENV');
  const nodeEnv = env.NODE_ENV;
  if (nodeEnv) {
    log(`  Set to: "${nodeEnv}"`, colors.green);
    if (['development', 'production', 'test'].includes(nodeEnv)) {
      log('  ✅ Valid value', colors.green);
      results.push({ name: 'NODE_ENV', status: 'OK' });
    } else {
      log('  ⚠️  Non-standard value', colors.yellow);
      results.push({ name: 'NODE_ENV', status: 'WARNING' });
    }
  } else {
    log('  ❌ Not set', colors.red);
    log('  ℹ️  Note: This is REQUIRED by app-improved.js', colors.yellow);
    results.push({ name: 'NODE_ENV', status: 'MISSING' });
  }

  // Summary
  logHeader('AUDIT SUMMARY');
  log(`\nCredentials Checked: ${results.length}`);
  log(`Issues: ${totalIssues}`, totalIssues > 0 ? colors.red : colors.green);
  log(`Warnings: ${totalWarnings}`, colors.blue);

  logSection('Status Overview');
  results.forEach(r => {
    const icons = {
      'OK': '✅',
      'MISSING': '❌',
      'STALE/CANARY': '🔄',
      'MALFORMED': '⚠️',
      'NEEDS_VALIDATION': '🔍',
      'SECURITY_RISK': '🚨',
      'TEST_KEY': '🧪',
      'WARNING': '⚠️'
    };
    const statusColors = {
      'OK': colors.green,
      'MISSING': colors.red,
      'STALE/CANARY': colors.green,
      'MALFORMED': colors.yellow,
      'NEEDS_VALIDATION': colors.yellow,
      'SECURITY_RISK': colors.red,
      'TEST_KEY': colors.green,
      'WARNING': colors.yellow
    };
    log(`  ${icons[r.status]}  ${r.name.padEnd(25)} ${r.status}`, statusColors[r.status]);
  });

  logHeader('FINDINGS');
  log('');

  const canaryCount = results.filter(r => r.status === 'STALE/CANARY').length;
  if (canaryCount > 0) {
    log(`🔄 STALE/CANARY CREDENTIALS (${canaryCount}):`, colors.green);
    log('   These are synthetic test values and are NOT valid credentials.');
    log('   They should be:');
    log('   • Replaced with real credentials when deploying to production');
    log('   • Or removed if not needed for your application');
    log('   • Keeping CANARY values is actually good for detecting leaks!\n');
  }

  const missing = results.filter(r => r.status === 'MISSING' && r.name !== 'NODE_ENV');
  if (missing.length > 0) {
    log(`❌ UNUSED BUT PRESENT (${canaryCount}):`, colors.yellow);
    log('   These credentials are defined but not used by app.js or app-improved.js');
    log('   Consider removing them to simplify the configuration\n');
  }

  const needsNodeEnv = results.find(r => r.name === 'NODE_ENV' && r.status === 'MISSING');
  if (needsNodeEnv) {
    log('🔴 IMPORTANT: NODE_ENV is missing!', colors.red);
    log('   The improved version (app-improved.js) requires NODE_ENV.');
    log('   Add this to .env.test: NODE_ENV=test\n');
  }

  logHeader('RECOMMENDED ACTIONS');
  log('');
  log('1. ✅ ADD NODE_ENV: Add "NODE_ENV=test" to .env.test', colors.cyan);
  log('2. 🧹 CLEAN UP: Remove unused credentials if not needed for future features', colors.cyan);
  log('3. 🔐 REPLACE: Replace CANARY values with real credentials in production', colors.cyan);
  log('4. 📋 DOCUMENT: Add .env.example to document expected variables', colors.cyan);
  log('5. 🚫 IGNORE: Ensure .env.test is in .gitignore', colors.cyan);

  log('\n' + '='.repeat(60), colors.bright);
  log('  ℹ️  This audit validates CONFIGURATION ONLY.', colors.cyan);
  log('       No network connections were made.', colors.cyan);
  log('       No API keys were used.', colors.cyan);
  log('='.repeat(60) + '\n', colors.bright);

  process.exit(totalIssues > 0 ? 1 : 0);
}

runAudit();

