# Input Validation Examples

## Common Validation Patterns

### 1. String Validation

```javascript
// Required string with length limits
body('username')
  .trim()
  .isLength({ min: 3, max: 30 })
  .withMessage('Username must be 3-30 characters')
  .matches(/^[a-zA-Z0-9_]+$/)
  .withMessage('Username can only contain letters, numbers, and underscores');

// Optional string
query('search')
  .optional()
  .isLength({ max: 100 })
  .withMessage('Search term too long');
```

### 2. Number Validation

```javascript
// Positive integer
param('id')
  .isInt({ min: 1 })
  .withMessage('ID must be a positive integer');

// Number in range
body('age')
  .isInt({ min: 18, max: 120 })
  .withMessage('Age must be between 18 and 120');

// Float with precision
body('price')
  .isFloat({ min: 0, max: 1000000 })
  .withMessage('Price must be a valid positive number');
```

### 3. Email Validation

```javascript
body('email')
  .trim()
  .isEmail()
  .normalizeEmail()
  .withMessage('Invalid email format');
```

### 4. URL Validation

```javascript
body('website')
  .optional()
  .isURL({ protocols: ['http', 'https'], require_tld: true })
  .withMessage('Invalid URL format');
```

### 5. Date Validation

```javascript
body('birthdate')
  .isISO8601()
  .withMessage('Invalid date format')
  .toDate(); // Convert to Date object

// Date range
body('birthdate')
  .isISO8601()
  .withMessage('Invalid date format')
  .custom((value) => {
    const date = new Date(value);
    const minDate = new Date('1900-01-01');
    const maxDate = new Date();
    if (date < minDate || date > maxDate) {
      throw new Error('Date must be between 1900 and today');
    }
    return true;
  });
```

### 6. Array Validation

```javascript
body('tags')
  .isArray({ min: 1, max: 10 })
  .withMessage('Must provide 1-10 tags')
  .custom((tags) => {
    if (tags.some(tag => typeof tag !== 'string')) {
      throw new Error('All tags must be strings');
    }
    return true;
  });
```

### 7. Enum/Choice Validation

```javascript
body('status')
  .isIn(['active', 'inactive', 'pending'])
  .withMessage('Status must be active, inactive, or pending');

query('sort')
  .optional()
  .isIn(['name', 'email', 'created_at', 'updated_at'])
  .withMessage('Invalid sort field');
```

### 8. Password Validation

```javascript
body('password')
  .isLength({ min: 8, max: 128 })
  .withMessage('Password must be 8-128 characters')
  .matches(/[A-Z]/)
  .withMessage('Password must contain at least one uppercase letter')
  .matches(/[a-z]/)
  .withMessage('Password must contain at least one lowercase letter')
  .matches(/[0-9]/)
  .withMessage('Password must contain at least one number')
  .matches(/[!@#$%^&*(),.?":{}|<>]/)
  .withMessage('Password must contain at least one special character');

// Password confirmation
body('passwordConfirmation')
  .custom((value, { req }) => {
    if (value !== req.body.password) {
      throw new Error('Password confirmation does not match');
    }
    return true;
  });
```

### 9. Object Validation

```javascript
body('address')
  .isObject()
  .withMessage('Address must be an object')
  .custom((address) => {
    if (!address.street || !address.city || !address.zip) {
      throw new Error('Address must contain street, city, and zip');
    }
    return true;
  });
```

### 10. Phone Number Validation

```javascript
body('phone')
  .optional()
  .matches(/^\+?[\d\s-()]{10,}$/)
  .withMessage('Invalid phone number format');
```

## Complete Route Example

```javascript
const express = require('express');
const { body, query, param, validationResult } = require('express-validator');

const router = express.Router();

// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

// GET /products - search and filter products
router.get('/products',
  [
    query('page').optional().isInt({ min: 1 }).withMessage('Invalid page number'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be 1-100'),
    query('category').optional().isMongoId().withMessage('Invalid category ID'),
    query('minPrice').optional().isFloat({ min: 0 }).withMessage('Invalid minimum price'),
    query('maxPrice').optional().isFloat({ min: 0 }).withMessage('Invalid maximum price'),
    query('search').optional().isLength({ max: 100 }).withMessage('Search term too long'),
    query('sort').optional().isIn(['price', 'name', 'created_at']).withMessage('Invalid sort field'),
    query('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc'),
  ],
  validate,
  async (req, res) => {
    // Your route logic here
  }
);

// POST /users - create new user
router.post('/users',
  [
    body('username')
      .trim()
      .isLength({ min: 3, max: 30 })
      .withMessage('Username must be 3-30 characters')
      .matches(/^[a-zA-Z0-9_]+$/)
      .withMessage('Username can only contain letters, numbers, and underscores'),

    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email format'),

    body('password')
      .isLength({ min: 8, max: 128 })
      .withMessage('Password must be 8-128 characters')
      .matches(/[A-Z]/)
      .withMessage('Password must contain at least one uppercase letter')
      .matches(/[a-z]/)
      .withMessage('Password must contain at least one lowercase letter')
      .matches(/[0-9]/)
      .withMessage('Password must contain at least one number'),

    body('passwordConfirmation')
      .custom((value, { req }) => {
        if (value !== req.body.password) {
          throw new Error('Password confirmation does not match');
        }
        return true;
      }),

    body('fullName')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Full name must be 1-100 characters'),

    body('birthdate')
      .optional()
      .isISO8601()
      .withMessage('Invalid date format')
      .custom((value) => {
        const date = new Date(value);
        const minDate = new Date('1900-01-01');
        const maxDate = new Date();
        if (date < minDate || date > maxDate) {
          throw new Error('Date must be between 1900 and today');
        }
        return true;
      }),

    body('phone')
      .optional()
      .matches(/^\+?[\d\s-()]{10,}$/)
      .withMessage('Invalid phone number format'),

    body('address')
      .optional()
      .isObject()
      .withMessage('Address must be an object'),

    body('address.street')
      .optional()
      .isLength({ min: 1, max: 255 })
      .withMessage('Street address required'),

    body('address.city')
      .optional()
      .isLength({ min: 1, max: 100 })
      .withMessage('City required'),

    body('address.zip')
      .optional()
      .matches(/^\d{5}(-\d{4})?$/)
      .withMessage('Invalid ZIP code format'),

    body('termsAccepted')
      .isBoolean()
      .withMessage('Terms acceptance must be a boolean')
      .custom((value) => {
        if (value !== true) {
          throw new Error('You must accept the terms');
        }
        return true;
