#!/usr/bin/env node

/**
 * Credential Format Analysis Tool
 * 
 * This script analyzes the FORMAT of credentials WITHOUT attempting
 * to connect to external services or validate actual credential validity.
 * 
 * SECURITY NOTE: This is for format analysis only. Do NOT attempt to
 * validate credential validity as these are canary values designed
 * for exfiltration detection.
 */

require('dotenv').config({ path: '.env.test' });

const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
};

console.log(`\n${colors.cyan}╔═══════════════════════════════════════════════════════════════════════════╗${colors.reset}`);
console.log(`${colors.cyan}║          CREDENTIAL FORMAT ANALYSIS (NO CONNECTIVITY TESTS)               ║${colors.reset}`);
console.log(`${colors.cyan}╚═══════════════════════════════════════════════════════════════════════════╝${colors.reset}\n`);

const issues = [];
const warnings = [];
const info = [];

// ============================================================================
// ANALYSIS FUNCTIONS
// ============================================================================

/**
 * Check if string contains canary indicators
 */
const isCanaryValue = (value) => {
  const canaryPatterns = ['CANARY', 'test123', 'example', 'placeholder', 'fake'];
  return canaryPatterns.some(pattern => 
    value.toUpperCase().includes(pattern.toUpperCase())
  );
};

/**
 * Analyze DATABASE_URL format
 */
const analyzeDatabaseUrl = () => {
  const url = process.env.DATABASE_URL;

  console.log(`${colors.blue}📦 DATABASE_URL${colors.reset}`);

  if (!url) {
    console.log(`  ${colors.red}✗ Not set${colors.reset}`);
    issues.push('DATABASE_URL is not defined');
    return;
  }

  try {
    const parsed = new URL(url);

    console.log(`  ${colors.green}✓ Format valid${colors.reset}`);
    console.log(`  Protocol:     ${parsed.protocol.replace(':', '')}`);
    console.log(`  Host:         ${parsed.hostname}`);
    console.log(`  Port:         ${parsed.port || 'default'}`);
    console.log(`  Database:     ${parsed.pathname.substring(1)}`);
    console.log(`  Username:     ${parsed.username}`);
    console.log(`  Password:     ${parsed.password ? '***SET***' : 'NOT SET'}`);

    if (isCanaryValue(url)) {
      console.log(`  ${colors.yellow}⚠ Contains CANARY indicator${colors.reset}`);
      warnings.push('DATABASE_URL contains "CANARY" - appears to be a test value');
    }

    if (parsed.hostname === 'db.internal' || parsed.hostname.includes('internal')) {
      console.log(`  ${colors.yellow}⚠ Points to internal/private network${colors.reset}`);
      warnings.push('DATABASE_URL hostname suggests internal network that may not exist');
    }

  } catch (error) {
    console.log(`  ${colors.red}✗ Invalid URL format: ${error.message}${colors.reset}`);
    issues.push(`DATABASE_URL has invalid URL format: ${error.message}`);
  }
  console.log();
};

/**
 * Analyze AWS credentials format
 */
const analyzeAwsCredentials = () => {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  console.log(`${colors.blue}☁️  AWS CREDENTIALS${colors.reset}`);

  if (!accessKeyId || !secretAccessKey) {
    console.log(`  ${colors.red}✗ Not fully set${colors.reset}`);
    issues.push('AWS credentials are incomplete');
    return;
  }

  // AWS Access Key ID format: 20 alphanumeric characters
  const accessKeyIdRegex = /^[A-Z0-9]{20}$/;

  if (accessKeyIdRegex.test(accessKeyId)) {
    console.log(`  ${colors.green}✓ Access Key ID format valid (${accessKeyId.length} chars)${colors.reset}`);
  } else {
    console.log(`  ${colors.red}✗ Access Key ID format invalid${colors.reset}`);
    issues.push('AWS_ACCESS_KEY_ID does not match expected format (20 alphanumeric chars)');
  }

  // AWS Secret Access Key format: 40 characters
  if (secretAccessKey.length === 40) {
    console.log(`  ${colors.green}✓ Secret Access Key format valid (${secretAccessKey.length} chars)${colors.reset}`);
  } else {
    console.log(`  ${colors.red}✗ Secret Access Key length invalid (${secretAccessKey.length} chars)${colors.reset}`);
    issues.push(`AWS_SECRET_ACCESS_KEY has invalid length (${secretAccessKey.length}, expected 40)`);
  }

  if (isCanaryValue(accessKeyId) || isCanaryValue(secretAccessKey)) {
    console.log(`  ${colors.yellow}⚠ Contains CANARY indicator${colors.reset}`);
    warnings.push('AWS credentials contain "CANARY" - appear to be test values');
  }

  console.log();
};

/**
 * Analyze Anthropic API key format
 */
const analyzeAnthropicApiKey = () => {
  const apiKey = process.env.ANTHROPIC_API_KEY;

  console.log(`${colors.blue}🤖 ANTHROPIC_API_KEY${colors.reset}`);

  if (!apiKey) {
    console.log(`  ${colors.red}✗ Not set${colors.reset}`);
    issues.push('ANTHROPIC_API_KEY is not defined');
    return;
  }

  // Anthropic API key format: sk-ant- followed by alphanumeric
  const anthropicKeyRegex = /^sk-ant-[a-zA-Z0-9_-]{20,}$/;

  if (anthropicKeyRegex.test(apiKey)) {
    console.log(`  ${colors.green}✓ Format valid (starts with sk-ant-)${colors.reset}`);
    console.log(`  Length: ${apiKey.length} characters`);
  } else {
    console.log(`  ${colors.red}✗ Format invalid${colors.reset}`);
    console.log(`  Expected format: sk-ant- followed by characters`);
    issues.push('ANTHROPIC_API_KEY does not match expected format');
  }

  if (isCanaryValue(apiKey)) {
    console.log(`  ${colors.yellow}⚠ Contains CANARY indicator${colors.reset}`);
    warnings.push('ANTHROPIC_API_KEY contains "CANARY" - appears to be a test value');
  }

  console.log();
};

/**
 * Analyze Stripe API key format
 */
const analyzeStripeKey = () => {
  const secretKey = process.env.STRIPE_SECRET_KEY;

  console.log(`${colors.blue}💳 STRIPE_SECRET_KEY${colors.reset}`);

  if (!secretKey) {
    console.log(`  ${colors.red}✗ Not set${colors.reset}`);
    issues.push('STRIPE_SECRET_KEY is not defined');
    return;
  }

  // Stripe secret key format: sk-live- or sk-test- followed by characters
  const stripeKeyRegex = /^sk_(live|test)_[a-zA-Z0-9]{24,}$/;

  if (stripeKeyRegex.test(secretKey)) {
    const mode = secretKey.startsWith('sk-live-') ? 'LIVE' : 'TEST';
    console.log(`  ${colors.green}✓ Format valid (${mode} mode)${colors.reset}`);
    console.log(`  Length: ${secretKey.length} characters`);
  } else {
    console.log(`  ${colors.red}✗ Format invalid${colors.reset}`);
    console.log(`  Expected format: sk-live- or sk-test- followed by characters`);
    issues.push('STRIPE_SECRET_KEY does not match expected format');
  }

  if (isCanaryValue(secretKey)) {
    console.log(`  ${colors.yellow}⚠ Contains CANARY indicator${colors.reset}`);
    warnings.push('STRIPE_SECRET_KEY contains "CANARY" - appears to be a test value');
  }

  if (secretKey.includes('CANARY-stripe-key')) {
    console.log(`  ${colors.yellow}⚠ Test key format appears synthetic${colors.reset}`);
  }

  console.log();
};

/**
 * Analyze Logfire token format
 */
const analyzeLogfireToken = () => {
  const token = process.env.LOGFIRE_TOKEN;

  console.log(`${colors.blue}📊 LOGFIRE_TOKEN${colors.reset}`);

  if (!token) {
    console.log(`  ${colors.red}✗ Not set${colors.reset}`);
    issues.push('LOGFIRE_TOKEN is not defined');
    return;
  }

  console.log(`  ${colors.green}✓ Token set${colors.reset}`);
  console.log(`  Length: ${token.length} characters`);

  if (isCanaryValue(token)) {
    console.log(`  ${colors.yellow}⚠ Contains CANARY indicator${colors.reset}`);
    warnings.push('LOGFIRE_TOKEN contains "CANARY" - appears to be a test value');
  }

  console.log();
};

/**
 * Check Node.js environment
 */
const checkEnvironment = () => {
  console.log(`${colors.blue}🔧 ENVIRONMENT${colors.reset}`);

  console.log(`  NODE_ENV:      ${process.env.NODE_ENV || colors.yellow}'NOT SET'${colors.reset}`);
  console.log(`  PORT:          ${process.env.PORT || colors.yellow}'NOT SET (will use default)'${colors.reset}`);

  if (!process.env.NODE_ENV) {
    warnings.push('NODE_ENV is not set (will default to "development")');
  }

  console.log();
};

/**
 * Check application requirements
 */
const checkAppRequirements = () => {
  console.log(`${colors.blue}📋 APPLICATION REQUIREMENTS${colors.reset}`);

  const originalAppUsesDatabase = false;
  const originalAppUsesAws = false;
  const originalAppUsesAnthropic = false;
  const originalAppUsesStripe = false;
  const originalAppUsesLogfire = false;

  console.log(`  Based on app.js analysis:`);
  console.log(`    Database layer:        ${originalAppUsesDatabase ? colors.red + 'NEEDED' + colors.reset : colors.green + 'NOT NEEDED' + colors.reset}`);
  console.log(`    AWS integration:       ${originalAppUsesAws ? colors.red + 'NEEDED' + colors.reset : colors.green + 'NOT NEEDED' + colors.reset}`);
  console.log(`    Anthropic AI:          ${originalAppUsesAnthropic ? colors.red + 'NEEDED' + colors.reset : colors.green + 'NOT NEEDED' + colors.reset}`);
  console.log(`    Stripe payments:       ${originalAppUsesStripe ? colors.red + 'NEEDED' + colors.reset : colors.green + 'NOT NEEDED' + colors.reset}`);
  console.log(`    Logfire logging:       ${originalAppUsesLogfire ? colors.red + 'NEEDED' + colors.reset : colors.green + 'NOT NEEDED' + colors.reset}`);

  if (!originalAppUsesDatabase && process.env.DATABASE_URL) {
    info.push('DATABASE_URL is set but app.js has no database layer');
  }
  if (!originalAppUsesAws && (process.env.AWS_ACCESS_KEY_ID || process.env.AWS_SECRET_ACCESS_KEY)) {
    info.push('AWS credentials are set but app.js has no AWS integration');
  }
  if (!originalAppUsesAnthropic && process.env.ANTHROPIC_API_KEY) {
    info.push('ANTHROPIC_API_KEY is set but app.js has no AI features');
  }
  if (!originalAppUsesStripe && process.env.STRIPE_SECRET_KEY) {
    info.push('STRIPE_SECRET_KEY is set but app.js has no payment processing');
  }
  if (!originalAppUsesLogfire && process.env.LOGFIRE_TOKEN) {
    info.push('LOGFIRE_TOKEN is set but app.js has no external logging');
  }

  console.log();
};

// ============================================================================
// RUN ANALYSIS
// ============================================================================

try {
  checkEnvironment();
  checkAppRequirements();
  analyzeDatabaseUrl();
  analyzeAwsCredentials();
  analyzeAnthropicApiKey();
  analyzeStripeKey();
  analyzeLogfireToken();

} catch (error) {
  console.error(`\n${colors.red}Error during analysis:${colors.reset}`, error.message);
  process.exit(1);
}

// ============================================================================
// SUMMARY
// ============================================================================

console.log(`${colors.cyan}═══════════════════════════════════════════════════════════════════════════${colors.reset}`);
console.log(`${colors.cyan}SUMMARY${colors.reset}`);
console.log(`${colors.cyan}═══════════════════════════════════════════════════════════════════════════${colors.reset}\n`);

if (issues.length > 0) {
  console.log(`${colors.red}🚨 ISSUES (${issues.length}):${colors.reset}`);
  issues.forEach(issue => console.log(`  • ${issue}`));
  console.log();
}

if (warnings.length > 0) {
  console.log(`${colors.yellow}⚠️  WARNINGS (${warnings.length}):${colors.reset}`);
  warnings.forEach(warning => console.log(`  • ${warning}`));
  console.log();
}

if (info.length > 0) {
  console.log(`${colors.blue}ℹ️  INFO (${info.length}):${colors.reset}`);
