  console.log();
}

console.log(`${colors.cyan}═══════════════════════════════════════════════════════════════════════════${colors.reset}\n`);

if (issues.length === 0 && warnings.length === 0) {
  console.log(`${colors.green}✓ All credential formats are valid${colors.reset}\n`);
