files.forEach(file => {
  if (fs.existsSync(file)) {
    const content = fs.readFileSync(file, 'utf8');
    const matches = content.match(/process\.env\.(\w+)/g);
    if (matches) {
      matches.forEach(match => {
        const varName = match.replace('process.env.', '');
        usedVars.add(varName);
      });
    }
  }
});

