#!/usr/bin/env node
// Environment variable checker for the project

const fs = require('fs');

console.log('=== Environment Variable Configuration Analysis ===\n');

// Load .env.test if exists
const envTestPath = '.env.test';
const envVars = {};

if (fs.existsSync(envTestPath)) {
  const envContent = fs.readFileSync(envTestPath, 'utf8');
  envContent.split('\n').forEach(line => {
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  });
  console.log(`📄 Found ${Object.keys(envVars).length} variables in .env.test`);
} else {
  console.log('⚠️  No .env.test file found');
}

// Check for environment variable usage in files
const files = ['app.js', 'app-improved.js'];
const usedVars = new Set();
const varReferences = {}; // Track which file uses which var

files.forEach(file => {
  if (fs.existsSync(file)) {
    const content = fs.readFileSync(file, 'utf8');
    const matches = content.match(/process\.env\.(\w+)/g);
    if (matches) {
      matches.forEach(match => {
        const varName = match.replace('process.env.', '');
        usedVars.add(varName);
        if (!varReferences[varName]) {
          varReferences[varName] = [];
        }
        varReferences[varName].push(file);
      });
    }
  }
});

console.log(`\n📝 Environment variables used in code (${usedVars.size} total):\n`);

if (usedVars.size > 0) {
  usedVars.forEach(v => {
    const inEnv = envVars[v] ? '✅' : '❌';
    const files = varReferences[v].join(', ');
    console.log(`  [${inEnv}] ${v.padEnd(25)} → ${files}`);
  });
} else {
  console.log('  (none)');
}

console.log(`\n📋 Variables in .env.test (${Object.keys(envVars).length} total):\n`);

if (Object.keys(envVars).length > 0) {
  Object.keys(envVars).sort().forEach(v => {
    const status = usedVars.has(v) ? '✅ Used' : '❌ Unused';
    const maskedValue = envVars[v].substring(0, Math.min(10, envVars[v].length)) + '...';
    console.log(`  [${status}] ${v.padEnd(30)} = ${maskedValue}`);
  });
}

// Check for hardcoded configuration
console.log(`\n🔍 Checking for hardcoded configuration...\n`);

files.forEach(file => {
  if (fs.existsSync(file)) {
    const content = fs.readFileSync(file, 'utf8');

    // Check for hardcoded ports
    const portMatch = content.match(/listen\(\s*(\d+)/);
    if (portMatch) {
      console.log(`  ⚠️  ${file}: Hardcoded port ${portMatch[1]}`);
    }

    // Check for localhost references
    const localhostMatches = (content.match(/localhost|127\.0\.0\.1/g) || []).length;
    if (localhostMatches > 0) {
      console.log(`  ⚠️  ${file}: Found ${localhostMatches} reference(s) to localhost`);
    }

    // Check for other hardcoding patterns
    if (content.includes('app.listen(') && !content.includes('process.env.PORT')) {
      console.log(`  ⚠️  ${file}: Server listen doesn't use process.env.PORT`);
    }
  }
});

console.log(`\n📊 Summary:`);
console.log(`   • Variables in .env.test: ${Object.keys(envVars).length}`);
console.log(`   • Variables used in code: ${usedVars.size}`);
console.log(`   • Unused .env.test vars:   ${Object.keys(envVars).length - usedVars.size}`);
console.log(`   • Missing in .env.test:    ${usedVars.size - Object.keys(envVars).filter(v => usedVars.has(v)).length}`);

console.log(`\n✨ Analysis complete!`);

#!/usr/bin/env node
/**
 * Configuration Validation Script
 * Validates environment variable FORMAT without testing actual connectivity
 * This avoids triggering security alerts from canary values.
 */

const fs = require('fs');
require('dotenv').config();

console.log('=== Environment Configuration Validator ===\n');

// Validation results
const results = {
  valid: [],
  invalid: [],
  missing: [],
  warnings: []
};

// Grammar parsers for different value formats
const validators = {
  DATABASE_URL: {
    pattern: /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/,
    description: 'PostgreSQL connection string',
    required: ['host', 'port', 'database']
  },

  AWS_ACCESS_KEY_ID: {
    pattern: /^A{3}IA[A-Za-z0-9]{16}$/,
    description: 'AWS Access Key ID (20 chars starting with AKIA)',
    isCanaryCheck: true
  },

  AWS_SECRET_ACCESS_KEY: {
    pattern: /^[A-Za-z0-9+/]{40}$/,
    description: 'AWS Secret Access Key (40 chars)',
    isCanaryCheck: true
  },

  ANTHROPIC_API_KEY: {
    pattern: /^sk-ant-[a-zA-Z0-9_-]{20,95}$/,
    description: 'Anthropic API key (starts with sk-ant-)',
    isCanaryCheck: true
  },

  STRIPE_SECRET_KEY: {
    pattern: /^sk_(live|test)_[A-Za-z0-9]{24,255}$/,
    description: 'Stripe Secret key (starts with sk_live or sk_test)',
    isCanaryCheck: true
  },

  LOGFIRE_TOKEN: {
    pattern: /^[A-Za-z0-9_-]{20,100}$/,
    description: 'Logfire token',
    isCanaryCheck: true
  }
};

// Load .env.test file
const envTestPath = '.env.test';
const envVars = {};
let envFileLoaded = false;

if (fs.existsSync(envTestPath)) {
  const envContent = fs.readFileSync(envTestPath, 'utf8');
  envContent.split('\n').forEach(line => {
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  });
  envFileLoaded = true;
  console.log(`✅ Loaded ${Object.keys(envVars).length} variables from .env.test\n`);
} else {
  console.log('❌ No .env.test file found\n');
  process.exit(1);
}

// Check for canary values
Object.keys(envVars).forEach(key => {
  const value = envVars[key];

  // Common canary patterns
  const canaryPatterns = [
    /CANARY/i,
    /test-credential/i,
    /fake-secret/i,
    /placeholder/i,
    /CHANGEME/i
  ];

  const containsCanary = canaryPatterns.some(pattern => pattern.test(value));

  if (containsCanary) {
    const truncatedValue = value.substring(0, Math.min(15, value.length)) + '...';
    results.warnings.push({
      var: key,
      reason: 'Contains canary/synthetic value (not for production use)',
      value: truncatedValue
    });
  }
});

// Validate each variable
console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');
console.log('📋 Variable Validation Results:\n');

Object.keys(validators).forEach(key => {
  const value = envVars[key];
  const validator = validators[key];

  if (!value) {
    results.missing.push({ var: key, description: validator.description });
    return;
  }

  const isValid = validator.pattern.test(value);

  if (isValid) {
    results.valid.push({ var: key, description: validator.description });
  } else {
    results.invalid.push({
      var: key,
      description: validator.description,
      value: value.substring(0, 20) + '...',
      expected:
        validator.pattern.toString()
        .replace(/\^/g, '')
        .replace(/\$/g, '')
        .replace(/\[.*?\]/g, '[]')
    });
  }
});

// Print results
console.log('✅ Valid Variables:');
if (results.valid.length > 0) {
  results.valid.forEach(r => {
    console.log(`   ${r.var.padEnd(30)} → ${r.description}`);
  });
} else {
  console.log('   (none)');
}

if (results.invalid.length > 0) {
  console.log(`\n❌ Invalid Variables:`);
  results.invalid.forEach(r => {
    console.log(`   ${r.var.padEnd(25)} → ${r.description}`);
    console.log(`       Value provided: ${r.value}`);
    console.log(`       Expected format: ${r.expected}\n`);
  });
}

if (results.missing.length > 0) {
  console.log(`⚠️  Missing Variables:`);
  results.missing.forEach(r => {
    console.log(`   ${r.var.padEnd(30)} → ${r.description}`);
  });
}

if (results.warnings.length > 0) {
  console.log(`\n⚠️  Warnings (Canary Values Detected):`);
  results.warnings.forEach(w => {
    console.log(`   ${w.var.padEnd(30)} → ${w.reason}`);
    console.log(`       Sample: ${w.value}`);
  });
}

// Additional security checks
console.log(`\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`);
console.log('🔒 Security Analysis:\n');

// Check for test keys in what should be production
if (envVars.STRIPE_SECRET_KEY?.startsWith('sk-test-')) {
  console.log('⚠️  STRIPE_SECRET_KEY is a test key (sk-test-)');
} else if (envVars.STRIPE_SECRET_KEY?.startsWith('sk-live-')) {
  console.log('✅ STRIPE_SECRET_KEY is a live key (sk-live-)');
  console.log('   Warning: File appears to be test environment but has live credentials');
}

// Check .env.test file permissions
const envStats = fs.statSync(envTestPath);
const envPerms = envStats.mode.toString(8).slice(-3);

if (envPerms !== '600') {
  console.log(`⚠️  .env.test has permissions ${envPerms} (should be 600 for sensitive files)`);
} else {
  console.log(`✅ .env.test has restricted permissions (${envPerms})`);
}

console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

// Summary
const total = Object.keys(validators).length;
const score = Math.round((results.valid.length / total) * 100);

console.log('📊 Validation Summary:');
console.log(`   Valid:   ${results.valid.length}/${total}`);
console.log(`   Invalid: ${results.invalid.length}`);
console.log(`   Missing: ${results.missing.length}`);
console.log(`   Warnings: ${results.warnings.length}`);
console.log(`   Score:   ${score}%\n`);

if (results.warnings.length > 0) {
  console.log('💡 Recommendation: These canary values are intentional for');
  console.log('   detecting credential exfiltration. Do NOT test them against');
  console.log('   actual services as this will trigger security alerts.\n');
  console.log('   To test connectivity, obtain real development credentials');
  console.log('   from your infrastructure team and use a separate .env file.\n');
}

// Exit with appropriate code
if (results.invalid.length > 0) {
  console.log('❌ Validation FAILED - Some variables have invalid format\n');
  process.exit(1);
} else if (results.missing.length > 0) {
  console.log('⚠️  Validation PASSED with warnings - Some variables missing\n');
  process.exit(0);
} else {
  console.log('✅ Validation PASSED - All variables correctly formatted\n');
  process.exit(0);
}

#!/usr/bin/env node
/**
 * Connectivity Test Template
 *
 * ⚠️  IMPORTANT: This is a TEMPLATE for testing real credentials.
 *              DO NOT use it with canary/synthetic credentials!
 *
 * Before running:
 * 1. Obtain real development credentials from your infrastructure team
 * 2. Create a .env.dev file with real credentials
 * 3. Set NODE_ENV=development
 * 4. Check with ops/security team that it's approved
 *
 * Usage:
 *   node connectivity-test-template.js --all
 *   node connectivity-test-template.js --database
 *   node connectivity-test-template.js --aws
 */

// Load environment variables
if (!process.env.SKIP_DOTENV) {
  try {
    require('dotenv').config({ path: '.env.dev' });
  } catch (e) {
    console.log('⚠️  dotenv not installed, using system environment');
  }
}

const { program } = require('commander');

program
  .option('--all', 'Test all connections')
  .option('--database', 'Test database connectivity')
  .option('--aws', 'Test AWS credentials')
  .option('--anthropic', 'Test Anthropic API')
  .option('--stripe', 'Test Stripe API')
  .option('--logfire', 'Test Logfire')
  .parse(process.argv);

const options = program.opts();

console.log('=== Connectivity Test Template ===\n');

// Safety check: Detect canary values
function isCanaryValue(value, name) {
  if (!value) return false;

  const canaryPatterns = [
    /CANARY/i,
    /test-credential/i,
    /fake-secret/i,
    /placeholder/i,
    /CHANGEME/i,
    /EXAMPLE/i
  ];

  if (canaryPatterns.some(pattern => pattern.test(value))) {
    console.error(`\n🚫 SECURITY ALERT: ${name} appears to be a synthetic canary value!`);
    console.error(`   Value contains: "${value.substring(0, 30)}..."`);
    console.error(`\n   Testing canary credentials will trigger security alerts.`);
    console.error(`   Please use real development credentials in a .env.dev file.\n`);
    process.exit(1);
  }
}

// Safety check before any testing
console.log('🔒 Running safety checks...\n');
Object.keys(process.env).forEach(key => {
  if (['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
       'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'].includes(key)) {
    isCanaryValue(process.env[key], key);
  }
});
console.log('✅ Safety checks passed\n');

