// Secure Express.js application with comprehensive error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const crypto = require('crypto');

const app = express();

// ============================================================================
// SECURITY CONFIGURATION
// ============================================================================

// Environment validation
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;
const isProduction = NODE_ENV === 'production';

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logSecurityEvent('RATE_LIMIT_EXCEEDED', req.ip, req.path);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
    });
  },
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts, please try again later.',
  skipSuccessfulRequests: true,
});

// Request size limit - prevent payload overflow
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security-critical headers
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Request ID for tracing
app.use((req, res, next) => {
  req.id = crypto.randomBytes(16).toString('hex');
  res.setHeader('X-Request-ID', req.id);
  next();
});

// Logging
if (isProduction) {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// ============================================================================
// INPUT VALIDATION UTILITIES
// ============================================================================

/**
 * Validate request and handle validation errors
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logSecurityEvent('VALIDATION_FAILED', req.ip, req.path, { errors: errors.array() });
    return res.status(400).json({
      error: 'Validation failed',
      details: isProduction ? undefined : errors.array(),
    });
  }
  next();
};

/**
 * Sanitize string input
 */
const sanitizeString = (input, maxLength = 1000) => {
  if (typeof input !== 'string') return null;
  const trimmed = input.trim().substring(0, maxLength);
  // Remove potential XSS patterns
  return trimmed.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
};

/**
 * Sanitize email input
 */
const sanitizeEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const sanitized = sanitizeString(email, 254);
  if (!sanitized || !emailRegex.test(sanitized)) return null;
  return sanitized.toLowerCase();
};

/**
 * Sanitize numeric input
 */
const sanitizeNumber = (input, min = -Number.MAX_VALUE, max = Number.MAX_VALUE) => {
  const num = Number(input);
  if (isNaN(num) || num < min || num > max) return null;
  return num;
};

/**
 * Sanitize ID parameter
 */
const sanitizeId = (input) => {
  const id = sanitizeNumber(input, 1, Number.MAX_SAFE_INTEGER);
  return id ? Math.floor(id) : null;
};

// ============================================================================
// SECURITY EVENT LOGGING
// ============================================================================

/**
 * Log security events for monitoring
 */
const logSecurityEvent = (eventType, ip, path, details = {}) => {
  const logEntry = {
    timestamp: new Date().toISOString(),
    event_type: eventType,
    ip: ip,
    path: path,
    details: details,
    request_id: details.requestId || 'unknown',
  };

  if (isProduction) {
    // In production, send to security monitoring system
    console.warn('[SECURITY]', JSON.stringify(logEntry));
  } else {
    console.warn('[SECURITY]', JSON.stringify(logEntry, null, 2));
  }
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logSecurityEvent('NOT_FOUND', req.ip, req.path, {
    method: req.method,
    userAgent: req.get('user-agent'),
    requestId: req.id,
  });
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found.',
    requestId: req.id,
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  const errorId = crypto.randomBytes(16).toString('hex');

  // Log the full error
  console.error(`[ERROR ${errorId}]`, {
    timestamp: new Date().toISOString(),
    error: {
      message: err.message,
      stack: isProduction ? undefined : err.stack,
      name: err.name,
    },
    request: {
      id: req.id,
      method: req.method,
      path: req.path,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    },
  });

  // Log security-relevant errors
  if (err.name === 'UnauthorizedError' || err.status === 401 || err.status === 403) {
    logSecurityEvent('AUTHORIZATION_FAILED', req.ip, req.path, {
      error: err.message,
      requestId: req.id,
      errorId: errorId,
    });
  }

  // Send appropriate response
  const statusCode = err.status || 500;
  res.status(statusCode).json({
    error: isProduction ? 'Internal Server Error' : err.name,
    message: isProduction 
      ? 'An error occurred. Please contact support if the problem persists.' 
      : err.message,
    requestId: req.id,
    errorId: isProduction ? undefined : errorId,
  });
});

/**
 * Handle uncaught exceptions
 */
process.on('uncaughtException', (err) => {
  console.error('[UNCAUGHT EXCEPTION]', {
    timestamp: new Date().toISOString(),
    error: {
      message: err.message,
      stack: err.stack,
      name: err.name,
    },
  });
  // In production, you might want to gracefully shutdown
  if (isProduction) {
    process.exit(1);
  }
});

/**
 * Handle unhandled promise rejections
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', {
    timestamp: new Date().toISOString(),
    reason: reason,
    promise: promise,
  });
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint (no rate limiting for health checks)
app.get('/health', (req, res) => {
  // Validate query parameters if any
  const verbose = req.query.verbose === 'true' || req.query.verbose === '1';

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    request_id: req.id,
  };

  if (verbose && !isProduction) {
    healthData.environment = NODE_ENV;
    healthData.uptime = process.uptime();
    healthData.memory = process.memoryUsage();
  }

  res.json(healthData);
});

// Users endpoint with rate limiting
app.get('/users', limiter, [
  // Query parameter validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email'])
    .withMessage('Sort must be one of: id, name, email'),
  query('order')
    .optional()
    .isIn(['asc', 'desc'])
    .withMessage('Order must be either asc or desc'),
  query('search')
    .optional()
    .isString()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search term must be 100 characters or less'),
], validateRequest, (req, res) => {
  try {
    // Get validated/sanitized query parameters
    const limit = sanitizeNumber(req.query.limit, 1, 100) || 10;
    const offset = sanitizeNumber(req.query.offset, 0) || 0;
    const sort = sanitizeString(req.query.sort, 10) || 'id';
    const order = sanitizeString(req.query.order, 4) || 'asc';
    const search = sanitizeString(req.query.search, 100);

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Apply filtering if search term provided
    let users = allUsers;
    if (search) {
      const searchLower = search.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply sorting
    users.sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      return order === 'asc' ? comparison : -comparison;
    });

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: limit,
        offset: offset,
        request_id: req.id,
      },
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An error occurred while retrieving users.',
      request_id: req.id,
    });
  }
});

// User by ID endpoint with strict rate limiting
app.get('/users/:id', strictLimiter, [
  // Parameter validation
  param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
], validateRequest, (req, res) => {
  try {
    const userId = sanitizeId(req.params.id);

    if (!userId) {
      return res.status(400).json({
        error: 'Invalid ID',
        message: 'The provided user ID is invalid.',
        request_id: req.id,
      });
    }

    // Mock user data
    const users = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
      3: { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      4: { id: 4, name: 'Diana', email: 'diana@example.com' },
      5: { id: 5, name: 'Eve', email: 'eve@example.com' },
    };

    const user = users[userId];

    if (!user) {
      logSecurityEvent('USER_NOT_FOUND', req.ip, req.path, {
        userId: userId,
        requestId: req.id,
      });
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found.',
        request_id: req.id,
      });
    }

    res.json({
      data: user,
      meta: {
        request_id: req.id,
      },
    });
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An error occurred while retrieving the user.',
      request_id: req.id,
    });
  }
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing server shutdown after timeout');
    process.exit(1);
  }, 10000);
};

