/**
 * Improved Express application with security best practices
 * Focus on error handling, input validation, and security hardening
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const createError = require('http-errors');

const app = express();
const PORT = process.env.PORT || 3000;

// Security Middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent DoS

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// CORS configuration (if needed for cross-origin requests)
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      method: req.method,
      url: req.url,
      ip: req.ip,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      userAgent: req.get('user-agent') || 'unknown'
    };
    // Only log non-successful responses in detail
    if (res.statusCode >= 400) {
      console.error('[SECURITY] Request error:', JSON.stringify(logData));
    } else {
      console.log('[INFO] Request:', JSON.stringify(logData));
    }
  });
  next();
});

/**
 * Utility function to sanitize and escape HTML to prevent XSS
 * Could use a library like 'escape-html' or 'xss' in production
 */
function sanitizeOutput(data) {
  if (typeof data === 'string') {
    // Basic HTML entity encoding
    return data
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = {};
    for (const key in data) {
      if (Object.prototype.hasOwnProperty.call(data, key)) {
        sanitized[key] = sanitizeOutput(data[key]);
      }
    }
    return sanitized;
  }
  return data;
}

/**
 * Validation middleware to check for validation errors
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const errorMessages = errors.array().map(err => ({
      field: err.path || err.param,
      message: err.msg,
      value: err.value
    }));

    // Log validation failures for security monitoring
    console.warn('[SECURITY] Validation failed:', {
      url: req.url,
      ip: req.ip,
      errors: errorMessages
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errorMessages
    });
  }
  next();
};

// ============================================================
// Routes with proper error handling and validation
// ============================================================

/**
 * GET /health
 * Health check endpoint
 * Returns: 200 OK with server status
 */
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    };
    res.json(healthData);
  } catch (error) {
    console.error('[ERROR] Health check failed:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Health check failed'
    });
  }
});

/**
 * GET /users
 * Get list of users with query parameter validation
 * Query params:
 *   - limit: number of users to return (1-100, default: 10)
 *   - offset: pagination offset (>= 0, default: 0)
 *   - sort: field to sort by (enum: id, name, email)
 */
app.get('/users', [
  // Input validation for query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email'])
    .withMessage('Sort must be one of: id, name, email')
], validateRequest, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply validated query parameters
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;
    const sortBy = req.query.sort || 'id';

    // Sort users by the specified field
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sortBy] < b[sortBy]) return -1;
      if (a[sortBy] > b[sortBy]) return 1;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    // Sanitize output to prevent XSS
    const sanitizedUsers = sanitizeOutput(paginatedUsers);

    res.status(200).json({
      data: sanitizedUsers,
      meta: {
        total: users.length,
        limit,
        offset,
        returned: sanitizedUsers.length
      }
    });
  } catch (error) {
    console.error('[ERROR] Failed to retrieve users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

/**
 * GET /users/:id
 * Get a specific user by ID with path parameter validation
 */
app.get('/users/:id', [
  // Validate that id is a positive integer
  // Match the route parameter 'id'
], validateRequest, (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Additional validation since express-validator doesn't handle path params well in all versions
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: [{
          field: 'id',
          message: 'ID must be a positive integer',
          value: req.params.id
        }]
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      console.warn('[SECURITY] User not found:', { ip: req.ip, userId });
      return res.status(404).json({
        error: 'Not found',
        message: `User with ID ${userId} not found`
      });
    }

    // Sanitize output
    res.status(200).json({ data: sanitizeOutput(user) });
  } catch (error) {
    console.error('[ERROR] Failed to retrieve user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve user'
    });
  }
});

// ============================================================
// 404 Handler - Must be after all routes
// ============================================================
app.use((req, res) => {
  console.warn('[SECURITY] 404 Not Found:', {
    method: req.method,
    url: req.url,
    ip: req.ip
  });
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource was not found'
  });
});

// ============================================================
// Global Error Handler - Must be last
// ============================================================
app.use((err, req, res, next) => {
  // Log the full error for debugging
  console.error('[ERROR] Unhandled error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.status || err.statusCode || 500;
  const response = {
    error: statusMessages[statusCode] || 'Internal server error'
  };

  // Include error details only in development
  if (isDevelopment && statusCode !== 500) {
    response.message = err.message;
    response.details = err.details || null;
  }

  res.status(statusCode).json(response);
});

// Status code message mapping
const statusMessages = {
  400: 'Bad request',
  401: 'Unauthorized',
  403: 'Forbidden',
  404: 'Not found',
  409: 'Conflict',
  422: 'Unprocessable entity',
  429: 'Too many requests',
  500: 'Internal server error',
  503: 'Service unavailable'
};

// ============================================================
// Server startup with proper error handling
// ============================================================
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('[FATAL] Uncaught exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[FATAL] Unhandled rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

