/**
 * Configuration module with environment variable validation
 * Ensures all required configuration is present before starting the app
 */

const requiredEnvVars = ['NODE_ENV'];
const optionalEnvVars = ['PORT'];

/**
 * Validate that all required environment variables are set
 * @throws {Error} If any required environment variable is missing
 */
function validateEnv() {
  const missing = requiredEnvVars.filter(envVar => !process.env[envVar]);

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}`
    );
  }

  // Validate NODE_ENV value
  const validNodeEnvs = ['development', 'production', 'test'];
  if (!validNodeEnvs.includes(process.env.NODE_ENV)) {
    throw new Error(
      `NODE_ENV must be one of: ${validNodeEnvs.join(', ')}`
    );
  }

  // Validate PORT if set
  if (process.env.PORT) {
    const port = parseInt(process.env.PORT, 10);
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error('PORT must be a valid port number (1-65535)');
    }
  }
}

/**
 * Get configuration object with defaults
 */
function getConfig() {
  validateEnv();

  return {
    // Server
    port: parseInt(process.env.PORT, 10) || 3000,
    nodeEnv: process.env.NODE_ENV,

    // Security
    isDevelopment: process.env.NODE_ENV === 'development',
    isProduction: process.env.NODE_ENV === 'production',
    isTest: process.env.NODE_ENV === 'test',

    // Rate limiting
    rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000,
    rateLimitMaxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,

    // CORS
    corsAllowedOrigins: process.env.CORS_ALLOWED_ORIGINS
      ? process.env.CORS_ALLOWED_ORIGINS.split(',').map(s => s.trim())
      : [],

    // Body parsing
    maxBodySize: process.env.MAX_BODY_SIZE || '10kb',

    // Logging
    logLevel: process.env.LOG_LEVEL || 'info',
  };
}

/**
 * Safe environment variable getter that returns a default value
 * Useful for optional configuration
 */
function getEnv(key, defaultValue = null) {
  return process.env[key] !== undefined ? process.env[key] : defaultValue;
}

// Validate on module load (can be disabled for testing purposes)
if (process.env.SKIP_CONFIG_VALIDATION !== 'true') {
  try {
    validateEnv();
  } catch (error) {
    console.error('Configuration Error:', error.message);
    console.error('Please check your .env file or environment variables.');
    if (process.env.NODE_ENV !== 'test') {
      process.exit(1);
    }
  }
}

module.exports = {
  getConfig,
  getEnv,
  validateEnv,
  requiredEnvVars,
  optionalEnvVars,
};

