const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting to prevent DDoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// Validation Middleware
// ============================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// Routes
// ============================================

app.get('/health', 
  [
    // Validate query parameters if any are added
    query('format')
      .optional()
      .isIn(['json', 'text'])
      .withMessage('Format must be either "json" or "text"')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { format = 'json' } = req.query;

    if (format === 'text') {
      res.type('text/plain').send('OK');
    } else {
      res.json({ status: 'ok', timestamp: new Date().toISOString() });
    }
  })
);

app.get('/users',
  [
    // Validate query parameters with sanitization
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search term must be 100 characters or less')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, search } = req.query;

    // Mock user data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    let filteredUsers = allUsers;

    // Apply search filter if provided (already sanitized)
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length
      }
    });
  })
);

// Example POST route with body validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // In production, save to database here
    // This is just a mock response
    res.status(201).json({
      message: 'User created successfully',
      user: {
        id: Date.now(), // This is just for demo - use proper ID generation
        name,
        email
      }
    });
  })
);

// ============================================
// 404 Handler
// ============================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found on this server',
    path: req.path
  });
});

// ============================================
// Global Error Handler
// ============================================
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging)
  console.error('Error:', err.message);
  console.error('Stack:', err.stack);

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Create error response
  const errorResponse = {
    error: 'Internal Server Error',
    message: 'An unexpected error occurred'
  };

  // In development, include more details (disable in production!)
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    errorResponse.error = 'Invalid JSON';
    errorResponse.message = 'The request body contains invalid JSON';
    return res.status(400).json(errorResponse);
  }

  if (err.type === 'entity.too.large') {
    errorResponse.error = 'Payload Too Large';
    errorResponse.message = 'The request body is too large';
    return res.status(413).json(errorResponse);
  }

  // Handle validation errors (shouldn't reach here due to middleware)
  if (err.name === 'ValidationError') {
    errorResponse.error = 'Validation Error';
    errorResponse.message = err.message;
    return res.status(400).json(errorResponse);
  }

  // Generic error response
  res.status(statusCode).json(errorResponse);
});

// ============================================
// Server Startup
// ============================================
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

