const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various security HTTP headers

// Rate limiting to prevent DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(limiter);

// Body parser with size limit to prevent buffer overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware (important for security auditing)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Validation middleware - checks for validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Don't expose detailed validation errors to client in production
    // Log the full error server-side for debugging
    console.error('Validation errors:', errors.array());
    return res.status(400).json({
      error: 'Invalid request parameters',
      // Only include error details in development
      ...(process.env.NODE_ENV === 'development' && { details: errors.array() })
    });
  }
  next();
};

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for security auditing
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details to client
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An unexpected error occurred',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Pass to global error handler
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', 
  // Validate query parameters with sanitization
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    query('sort').optional().isIn(['name', 'email', 'id']).withMessage('Sort must be name, email, or id'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply validated query parameters
      const limit = parseInt(req.query.limit) || users.length;
      const offset = parseInt(req.query.offset) || 0;
      const sort = req.query.sort || 'id';

      // Sort users (whitelist-based, no SQL injection risk)
      const sortedUsers = [...users].sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      // Pagination
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit,
          offset,
          count: paginatedUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example of a secure POST endpoint with validation
app.post('/users',
  [
    body('name').trim().notEmpty().isLength({ min: 1, max: 100 }).escape()
      .withMessage('Name is required and must be 1-100 characters'),
    body('email').trim().isEmail().normalizeEmail()
      .withMessage('Valid email is required'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // In a real app, you would save to database here
      const newUser = {
        id: Date.now(), // Simple ID generation (not production-ready)
        name, // Already sanitized
        email // Already normalized
      };

      // Return created resource with 201 status
      res.status(201).json(newUser);
    } catch (error) {
      next(error);
    }
  }
);

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

