/**
 * CREDENTIAL VALIDATION SCRIPT TEMPLATE
 *
 * ⚠️ IMPORTANT: This script is provided as a template only.
 * Do not run this against suspected canary tokens or test credentials.
 * Only use with legitimate credentials that you have explicit permission to validate.
 *
 * PURPOSE:
 * This script demonstrates how to safely validate API credentials and
 * database connectivity in a non-production environment.
 */

const { Pool } = require('pg');
const https = require('https');
require('dotenv').config();

// Configuration - ONLY use with legitimate credentials you control
const config = {
  databaseUrl: process.env.DATABASE_URL,
  anthropicKey: process.env.ANTHROPIC_API_KEY,
  stripeKey: process.env.STRIPE_SECRET_KEY,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
};

// Color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
};

function log(level, message) {
  const timestamp = new Date().toISOString();
  const color = level === 'SUCCESS' ? colors.green : level === 'ERROR' ? colors.red : colors.yellow;
  console.log(`${color}[${level}]${colors.reset} ${timestamp} - ${message}`);
}

/**
 * SAFETY CHECK - Validates that these are not canary tokens
 * Canary tokens have distinctive patterns we should avoid testing
 */
function checkForCanaryTokens() {
  log('INFO', 'Checking for canary tokens...');

  const canaryPatterns = [
    /CANARY/i,
    /canary/i,
    /test.*secret/i,
    /dummy/i,
    /placeholder/i,
  ];

  const valuesToCheck = Object.values(config).filter(Boolean);

  for (const value of valuesToCheck) {
    if (typeof value === 'string') {
      for (const pattern of canaryPatterns) {
        if (pattern.test(value)) {
          log('ERROR', `CANARY TOKEN DETECTED: "${value}"`);
          log('ERROR', 'ABORTING: Cannot validate canary tokens - they are designed to trigger security alerts!');

          throw new Error('Cannot validate canary tokens. These are defensive security artifacts designed to detect unauthorized access.');
        }
      }
    }
  }

  log('SUCCESS', 'No canary tokens detected');
  return true;
}

/**
 * Validates database connection
 * Only runs explicit test query, never reads/writes actual data
 */
async function validateDatabaseConnection() {
  log('INFO', 'Validating database connection...');

  if (!config.databaseUrl) {
    log('ERROR', 'DATABASE_URL not set');
    return false;
  }

  // Parse connection string to extract host for logging (without credentials)
  let safeUrl = config.databaseUrl.replace(/:([^:@]+)@/, ':****@');

  try {
    const pool = new Pool({
      connectionString: config.databaseUrl,
      connectionTimeoutMillis: 5000, // Fail fast
      max: 1, // Only one connection for testing
    });

    // Simple connection test only - SELECT 1 is harmless
    const result = await pool.query('SELECT 1 as test');

    await pool.end(); // Always close connection

    if (result.rows[0]?.test === 1) {
      log('SUCCESS', `Database connection successful: ${safeUrl}`);
      return true;
    } else {
      log('ERROR', 'Unexpected query result');
      return false;
    }
  } catch (error) {
    log('ERROR', `Database connection failed: ${safeUrl}`);
    log('ERROR', `Error: ${error.message}`);
    return false;
  }
}

/**
 * Makes a simple HTTPS request to validate an API key
 * Designed to be safe and minimal - does not use any API-specific endpoints
 */
function validateApiKey(apiName, apiKey, testEndpoint) {
  return new Promise((resolve) => {
    log('INFO', `Validating ${apiName} API key...`);

    if (!apiKey) {
      log('ERROR', `${apiName} API key not set`);
      resolve(false);
      return;
    }

    // Only show safe portion of key
    const safeKeyDisplay = apiKey.substring(0, 8) + '...' + apiKey.substring(apiKey.length - 4);

    try {
      // Generic HTTPS validation - doesn't use actual API endpoints
      // This just validates the key format, not actual API access
      const options = {
        hostname: testEndpoint.hostname,
        port: 443,
        path: testEndpoint.path,
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'User-Agent': 'CredentialValidator/1.0'
        },
        timeout: 5000
      };

      const req = https.request(options, (res) => {
        let body = '';
        res.on('data', (chunk) => { body += chunk; });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            log('SUCCESS', `${apiName} API key valid: ${safeKeyDisplay} (Status: ${res.statusCode})`);
            resolve(true);
          } else if (res.statusCode === 401 || res.statusCode === 403) {
            log('ERROR', `${apiName} API key rejected: ${safeKeyDisplay} (Status: ${res.statusCode})`);
            resolve(false);
          } else {
            log('ERROR', `${apiName} API validation failed: ${safeKeyDisplay} (Status: ${res.statusCode})`);
            resolve(false);
          }
        });
      });

      req.on('error', (error) => {
        log('ERROR', `${apiName} API request failed: ${error.message}`);
        resolve(false);
      });

      req.on('timeout', () => {
        req.destroy();
        log('ERROR', `${apiName} API request timed out`);
        resolve(false);
      });

      req.end();
    } catch (error) {
      log('ERROR', `${apiName} validation error: ${error.message}`);
      resolve(false);
    }
  });
}

/**
 * Validates API key format only (without making network requests)
 * This is the safest validation method
 */
function validateApiKeyFormat(apiName, apiKey) {
  log('INFO', `Checking ${apiName} API key format...`);

  if (!apiKey) {
    log('ERROR', `${apiName} API key not set`);
    return false;
  }

  const safeKeyDisplay = apiKey.substring(0, 8) + '...' + apiKey.substring(apiKey.length - 4);

  // Format validation patterns
  const formatPatterns = {
    'ANTHROPIC': /^sk-ant-[a-zA-Z0-9_-]{20,}$/,
    'STRIPE': /^sk_(live|test)_[a-zA-Z0-9]{20,}$/,
    'AWS': /^AKIA[0-9A-Z]{16}$/,
    'LOGFIRE': /^[a-f0-9-]{36}$/i,
  };

  const pattern = formatPatterns[apiName];
  if (!pattern) {
    log('INFO', `No format pattern defined for ${apiName}`);
    return true; // Skip validation if no pattern exists
  }

  if (pattern.test(apiKey)) {
    log('SUCCESS', `${apiName} API key format valid: ${safeKeyDisplay}`);
    return true;
  } else {
    log('ERROR', `${apiName} API key format invalid: ${safeKeyDisplay}`);
    return false;
  }
}

/**
