  }

  // Print summary
  console.log('\n' + '='.repeat(60));
  console.log('VALIDATION SUMMARY');
  console.log('='.repeat(60));

  for (const [service, valid] of Object.entries(results)) {
    const status = valid ? '✓' : '✗';
    const color = valid ? colors.green : colors.red;
