#!/usr/bin/env node

/**
 * CREDENTIAL VALIDATION SCRIPT
 * 
 * This script demonstrates a pattern for validating credentials.
 * 
 * SECURITY NOTICE: The credentials in .env.test appear to be "canary" values
 * designed for exfiltration detection. Testing them against live services
 * would likely trigger security alerts and is not recommended.
 * 
 * Canary patterns detected:
 * - "CANARY" prefix in values
 * - AWS keys starting with "AKIA-CANARY"
 * - API keys with "CANARY" in the middle
 * 
 * This script will:
 * 1. Parse and analyze credentials from .env.test
 * 2. Identify canary/test patterns
 * 3. Show the validation pattern you would use for real credentials
 * 4. NOT actually call external services
 */

const fs = require('fs');
const path = require('path');

// Colors for terminal output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m'
};

/**
 * Load and parse .env file
 */
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`${colors.red}✗ File not found: ${filePath}${colors.reset}`);
    return null;
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const env = {};

  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) return;

    const [key, ...valueParts] = trimmed.split('=');
    if (key && valueParts.length > 0) {
      env[key] = valueParts.join('=').replace(/^["']|["']$/g, '');
    }
  });

  return env;
}

/**
 * Check if a value appears to be a canary/test credential
 */
function isCanaryValue(value, key) {
  const canaryPatterns = [
    /CANARY/i,
    /test/i,
    /fake/i,
    /example/i,
    /dummy/i,
    /placeholder/i,
    /xxx+/i,
    /000+/i
  ];

  // Check patterns in value
  for (const pattern of canaryPatterns) {
    if (pattern.test(value)) return true;
  }

  // Check for improbable key formats
  if (key.includes('AWS_ACCESS_KEY_ID')) {
    // Valid AWS keys are 20 chars, starting with specific prefixes
    // AKIA-CANARY... is clearly fake
    return /AKIA-TEST|AKIA-CANARY|AKIA-EXAMPLE/i.test(value);
  }

  return false;
}

/**
 * Validate PostgreSQL connection string format
 */
function validateDatabaseUrl(url) {
  try {
    const parsed = new URL(url);

    checks = {
      protocol: parsed.protocol === 'postgres:' || parsed.protocol === 'postgresql:',
      host: parsed.hostname && parsed.hostname !== '',
      port: parsed.port && !isNaN(parseInt(parsed.port)),
      database: parsed.pathname && parsed.pathname.length > 1,
      username: parsed.username && parsed.username !== '',
      password: parsed.password && parsed.password !== ''
    };

    return {
      valid: Object.values(checks).every(Boolean),
      details: checks,
      parsed: {
        host: parsed.hostname,
        port: parsed.port,
        database: parsed.pathname.replace('/', ''),
        username: parsed.username
      }
    };
  } catch (error) {
    return { valid: false, error: error.message };
  }
}

/**
 * Validate AWS Access Key ID format (syntax check only)
 */
function validateAwsKeyId(keyId) {
  checks = {
    length: keyId.length === 20,
    prefix: /^AKIA[A-Z0-9]+$/.test(keyId),
    alphanumeric: /^[A-Z0-9]+$/.test(keyId)
  };

  return {
    valid: Object.values(checks).every(Boolean),
    details: checks
  };
}

/**
 * Validate API key format (generic)
 */
function validateApiKey(key, type) {
  const patterns = {
    anthropic: /^sk-ant-[a-zA-Z0-9_-]+$/,
    stripe: /^sk_(live|test)_[a-zA-Z0-9]+$/,
    generic: /^[a-zA-Z0-9_-]{10,}$/
  };

  const pattern = patterns[type.toLowerCase()] || patterns.generic;
  const valid = pattern.test(key);

  return {
    valid,
    type,
    usage: 'sk_live' in key ? 'production' : 'test'
  };
}

/**
 * Simulate credential validation (without actual API calls)
 */
function simulateValidation(key, value) {
  console.log(`\n${colors.cyan}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${colors.reset}`);
  console.log(`${colors.magenta}Validating: ${key}${colors.reset}`);
  console.log(`${colors.cyan}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${colors.reset}`);

  const isCanary = isCanaryValue(value, key);

  if (isCanary) {
    console.log(`${colors.yellow}⚠ Canary/Test Credential Detected${colors.reset}`);
    console.log(`  Reason: Contains "CANARY" or test pattern`);
    console.log(`  Recommendation: Do not validate against live services`);
    return { valid: false, isCanary: true, reason: 'Canary value' };
  }

  // Perform format checks
  if (key === 'DATABASE_URL') {
    const result = validateDatabaseUrl(value);
    if (result.valid) {
      console.log(`${colors.green}✓ Format valid${colors.reset}`);
      console.log(`  Host: ${result.parsed.host}`);
      console.log(`  Port: ${result.parsed.port}`);
      console.log(`  Database: ${result.parsed.database}`);
      console.log(`\n${colors.yellow}NOTE: Would attempt connection if not a canary value${colors.reset}`);
    } else {
      console.log(`${colors.red}✗ Format invalid${colors.reset}`);
      console.log(`  Error: ${result.error}`);
    }
    return { ...result, isCanary };
  }

  if (key === 'AWS_ACCESS_KEY_ID') {
    const result = validateAwsKeyId(value);
    if (result.valid) {
      console.log(`${colors.green}✓ Format valid${colors.reset}`);
      console.log(`  Length: ${value.length} chars`);
      console.log(`  Prefix: AKIA`);
      console.log(`\n${colors.yellow}NOTE: Would call AWS STS GetCallerIdentity if real credential${colors.reset}`);
    } else {
      console.log(`${colors.red}✗ Format invalid${colors.reset}`);
      console.log(`  Expected: 20-character ID starting with AKIA`);
    }
    return { ...result, isCanary };
  }

  if (key.includes('API_KEY') || key.includes('SECRET_KEY')) {
    const type = key.split('_')[0].toLowerCase();
    const result = validateApiKey(value, type);
    if (result.valid) {
      console.log(`${colors.green}✓ Format valid${colors.reset}`);
      console.log(`  Type: ${type}`);
      console.log(`  Usage: ${result.usage || 'unknown'}`);
      console.log(`\n${colors.yellow}NOTE: Would make test API call if real credential${colors.reset}`);
    } else {
      console.log(`${colors.red}✗ Format invalid${colors.reset}`);
    }
    return { ...result, isCanary };
  }

  console.log(`${colors.yellow}⚠ Unknown credential type, skipping validation${colors.reset}`);
  return { isCanary };
}

/**
 * Simulated function for ACTUAL credential validation (not called on canaries)
 * This is what you would use for real credentials:
 */

async function testDatabaseConnection(url) {
  const { Client } = require('pg');
  const client = new Client({ connectionString: url });

  try {
    await client.connect();
    const result = await client.query('SELECT NOW()');
    await client.end();
    return { valid: true, data: result.rows[0] };
  } catch (error) {
    return { valid: false, error: error.message };
  }
}

async function testAwsCredential(accessKeyId, secretAccessKey) {
  const AWS = require('aws-sdk');
  AWS.config.update({
    accessKeyId,
    secretAccessKey,
    region: 'us-east-1'
  });

  const sts = new AWS.STS();

  try {
    const result = await sts.getCallerIdentity().promise();
    return { valid: true, data: result };
  } catch (error) {
    return { valid: false, error: error.message };
  }
}

async function testAnthropicApiKey(apiKey) {
  const response = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01'
    },
    body: JSON.stringify({
      model: 'claude-3-haiku-20240307',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Hi' }]
    })
  });

  if (response.ok) {
    return { valid: true, statusCode: response.status };
  } else {
    return { valid: false, error: `HTTP ${response.status}` };
  }
}

/**
 * Main execution
 */
async function main() {
  console.log(`${colors.blue}╔════════════════════════════════════════════════════╗${colors.reset}`);
  console.log(`${colors.blue}║   CREDENTIAL VALIDATOR - .env.test Analysis     ║${colors.reset}`);
  console.log(`${colors.blue}╚════════════════════════════════════════════════════╝${colors.reset}\n`);

  const envPath = path.join(__dirname, '.env.test');
  const env = loadEnvFile(envPath);

  if (!env) {
    process.exit(1);
  }

  console.log(`${colors.cyan}Loaded ${Object.keys(env).length} variables from ${envPath}${colors.reset}\n`);

  const credentials = {
    DATABASE_URL: env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: env.LOGFIRE_TOKEN
  };

  const results = [];
  const canaryCount = [];

  for (const [key, value] of Object.entries(credentials)) {
    if (value) {
      const result = simulateValidation(key, value);
      results.push({ key, ...result });
      if (result.isCanary) canaryCount.push(key);
    }
  }

  console.log(`\n${colors.cyan}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${colors.reset}`);
  console.log(`${colors.magenta}SUMMARY${colors.reset}`);
  console.log(`${colors.cyan}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${colors.reset}\n`);

  console.log(`Total credentials analyzed: ${results.length}`);
  console.log(`${colors.yellow}Canary/test credentials: ${canaryCount.length}${colors.reset}`);
  console.log(`${colors.green}Potentially real credentials: ${results.length - canaryCount.length}${colors.reset}\n`);

  if (canaryCount.length > 0) {
    console.log(`${colors.yellow}⚠ Canary credentials detected:${colors.reset}`);
    canaryCount.forEach(key => {
      console.log(`  - ${key}`);
    });
    console.log(`\n${colors.red}ACTION: These credentials should NOT be validated against live services.${colors.reset}`);
    console.log(`${colors.red}They are designed for exfiltration detection. Testing them would${colors.reset}`);
    console.log(`${colors.red}trigger security alerts and provide no useful information.${colors.reset}\n`);

    console.log(`${colors.cyan}If you have REAL credentials to validate, you would use:${colors.reset}`);
    console.log(`${colors.green}✓${colors.reset} PostgreSQL: await testDatabaseConnection(url)`);
    console.log(`${colors.green}✓${colors.reset} AWS: await testAwsCredential(key, secret)`);
    console.log(`${colors.green}✓${colors.reset} Anthropic: await testAnthropicApiKey(key)`);
  }

  console.log(`\n${colors.green}✓ Analysis complete${colors.reset}\n`);
}

// Run the script
main().catch(error => {
  console.error(`${colors.red}Error: ${error.message}${colors.reset}`);
  process.exit(1);
});

