});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  // Log the error (in production, use a proper logging service)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Resource not found',
    path: req.path
  });
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be asc or desc')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply query parameters safely
      const limit = parseInt(req.query.limit) || users.length;
      const offset = parseInt(req.query.offset) || 0;
      const sort = req.query.sort || 'id';
      const order = req.query.order || 'asc';

      // Sort users safely (whitelist validated above)
      const sortedUsers = [...users].sort((a, b) => {
        if (a[sort] < b[sort]) return order === 'asc' ? -1 : 1;
        if (a[sort] > b[sort]) return order === 'asc' ? 1 : -1;
        return 0;
      });

      // Apply pagination
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit,
          offset,
          sort,
          order
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example protected endpoint with ID validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id);

      // In a real app, fetch from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          id: userId
        });
      }

      // Remove sensitive data before sending response
      const { id, name, email } = user;
      res.json({ id, name, email });
    } catch (error) {
      next(error);
    }
  }
);

// Example POST endpoint with body validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // In a real app, save to database
      const newUser = {
        id: Date.now(), // Simple ID generation
        name,
        email
      };

      res.status(201).json({
        message: 'User created successfully',
        data: { id: newUser.id, name: newUser.name }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Apply error handling middleware last
app.use(notFoundHandler);
app.use(errorHandler);

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

# Security Improvements Guide for app.js

## Executive Summary

This document outlines the security improvements made to `app.js` focusing on error handling and input validation following security best practices.

---

## Table of Contents

1. [Dependencies](#dependencies)
2. [Security Enhancements Implemented](#security-enhancements-implemented)
3. [Input Validation](#input-validation)
4. [Error Handling](#error-handling)
5. [Additional Security Recommendations](#additional-security-recommendations)
6. [Testing Security Improvements](#testing-security-improvements)

---

## Dependencies

Install the required security packages:

```bash
npm install helmet express-rate-limit express-validator
```

### Purpose of Dependencies
- **helmet**: Sets security-related HTTP headers
- **express-rate-limit**: Prevents DoS attacks by limiting request rates
- **express-validator**: Provides input validation & sanitization

---

## Security Enhancements Implemented

### 1. HTTP Security Headers (Helmet)

**What it does:**
- Sets Content Security Policy (CSP)
- Enables XSS protection
- Prevents MIME-type sniffing
- Sets HSTS (HTTP Strict Transport Security)
- Disables X-Powered-By header (information leakage prevention)

**Security Impact:**
```javascript
app.use(helmet());
```

### 2. Rate Limiting

**What it does:**
- Limits each IP to 100 requests per 15 minutes
- Prevents brute force attacks
- Mitigates DoS/DDoS attacks

**Configurable Parameters:**
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // Adjust based on your needs
  max: 100,                  // Adjust based on expected traffic
  message: 'Too many requests...'
});
```

### 3. Request Size Limits

**What it does:**
- Limits JSON body to 10KB
- Prevents memory exhaustion attacks
- Blocks malicious large payloads

```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### 4. Graceful Shutdown

**What it does:**
- Handles SIGTERM and SIGINT signals
- Ensures in-flight requests complete before shutdown
- Prevents data corruption

---

## Input Validation

### Validation Chain Pattern

```javascript
app.get('/endpoint',
  [
    // Validation rules here
  ],
  validateRequest,  // Middleware to check results
  (req, res) => {
    // Handler logic
  }
);
```

### Types of Validation

#### Query Parameters
```javascript
query('limit')
  .optional()
  .isInt({ min: 1, max: 100 })
  .withMessage('Limit must be between 1 and 100')
```

#### URL Parameters
```javascript
param('id')
  .isInt({ min: 1 })
  .withMessage('ID must be a positive integer')
```

#### Request Body
```javascript
body('email')
  .trim()
  .notEmpty()
  .isEmail()
  .normalizeEmail()
  .isLength({ max: 255 })
```

### Validation Best Practices

| Practice | Example | Purpose |
|----------|---------|---------|
| Type checking | `.isInt()` | Prevents type coercion attacks |
| Range limiting | `.isLength({ min: 2, max: 100 })` | Prevents buffer overflows |
| Whitelisting | `.isIn(['value1', 'value2'])` | Prevents injection |
| Trimming | `.trim()` | Removes whitespace attacks |
| Normalization | `.normalizeEmail()` | Standardizes input format |
| Pattern matching | `.matches(/^[a-zA-Z\s'-]+$/)` | Allows only safe characters |

### Security-Specific Validations

#### Email Validation
```javascript
body('email')
  .isEmail()                    // Validates email format
  .normalizeEmail()             // Normalizes to lower case
  .isLength({ max: 255 })       // Prevents long email attacks
```

#### Name Validation
```javascript
body('name')
  .trim()                        // Remove leading/trailing whitespace
  .matches(/^[a-zA-Z\s'-]+$/)    // Whitelist safe characters only
  .escape()                      // Escape HTML entities (optional)
```

#### ID Validation
```javascript
param('id')
  .isInt({ min: 1 })            // Prevents negative IDs
  .toInt()                      // Convert to integer safely
```

---

## Error Handling

### Centralized Error Handler

```javascript
const errorHandler = (err, req, res, next) => {
  // Log the error securely
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: err.stack })
  });
};
```

### Error Handling Principles

1. **Never expose stack traces in production**
   - Attackers can use stack traces for reconnaissance
   - Stack traces may reveal internal architecture

2. **Log security-relevant information**
   - Request timestamp
   - IP addresses
   - Request paths that failed
   - Error types (without sensitive details)

3. **Use appropriate HTTP status codes**
   - 400: Validation errors
   - 401: Authentication required
   - 403: Forbidden
   - 404: Not found
   - 429: Rate limited
   - 500: Server errors

4. **Try-catch blocks in route handlers**
   ```javascript
   (req, res, next) => {
     try {
       // Route logic
     } catch (error) {
       next(error);  // Forward to error handler
     }
   }
   ```

### 404 Handler

```javascript
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Resource not found',
    path: req.path
  });
};
```

**Security Benefit:**
- Prevents information disclosure through default Express 404 pages
- Provides consistent error response format

---

## Additional Security Recommendations

### 1. Environment-Based Configuration

```javascript
const isProduction = process.env.NODE_ENV === 'production';

// Apply stricter settings in production
if (isProduction) {
  app.disable('x-powered-by');
  app.set('trust proxy', 1);  // For rate limiting behind proxies
}
```

### 2. CORS Configuration

```bash
npm install cors
```

```javascript
const cors = require('cors');

// Whitelist allowed origins
const allowedOrigins = [
  'https://yourdomain.com',
  'https://app.yourdomain.com'
];

const corsOptions = {
  origin: function (origin, callback) {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));
```

### 3. Logging Solution

Replace `console.log` with a proper logging library:

```bash
npm install winston
```

```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}
```

### 4. Input Sanitization

For database queries, always use parameterized queries:

```javascript
// BAD - SQL Injection vulnerable
const query = `SELECT * FROM users WHERE id = ${req.params.id}`;

// GOOD - Parameterized query
const query = 'SELECT * FROM users WHERE id = ?';
db.query(query, [req.params.id]);
```

### 5. HTTPS Enforcement

```javascript
app.use((req, res, next) => {
  if (!req.secure && process.env.NODE_ENV === 'production') {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});
```

### 6. Security Headers (Manual override)

```javascript
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.removeHeader('X-Powered-By');
  next();
});
```

### 7. Request Timeout

```javascript
const timeout = require('connect-timeout');
app.use(timeout('30s'));
```

---

## Testing Security Improvements

### Test Suite Example

```javascript
const request = require('supertest');
const app = require('./app');

describe('Security Tests', () => {

  describe('Input Validation', () => {

    test('should reject invalid email', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Test', email: 'invalid-email' })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject SQL injection attempt', async () => {
      const response = await request(app)
        .get('/users/1\' OR \'1\'=\'1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should sanitize XSS in name', async () => {
      const response = await request(app)
        .post('/users')
        .send({ 
          name: '<script>alert("xss")</script>', 
          email: 'test@example.com' 
        })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });
  });

  describe('Rate Limiting', () => {

    test('should rate limit after threshold', async () => {
      const requests = Array(105).fill(null).map(() => 
        request(app).get('/health')
      );

      const responses = await Promise.all(requests);
      const rateLimited = responses.filter(r => r.status === 429);

      expect(rateLimited.length).toBeGreaterThan(0);
    });
  });

  describe('Error Handling', () => {

    test('should not expose stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/nonexistent-path')
        .expect(404);

      expect(response.body).not.toHaveProperty('stack');

      process.env.NODE_ENV = originalEnv;
    });
  });
});
```

---

## Security Checklist

### Input Validation
- [ ] All user inputs are validated
- [ ] Whitelist validation used instead of blacklist
- [ ] Type checking implemented
- [ ] Length limits enforced
- [ ] Special characters handled appropriately
- [ ] Email normalization performed
- [ ] HTML entity escaping applied

### Error Handling
- [ ] Centralized error handler implemented
- [ ] Stack traces not exposed in production
- [ ] Appropriate HTTP status codes used
- [ ] Errors logged securely
- [ ] 404 handler implemented
- [ ] Try-catch blocks in all route handlers

### Security Headers
- [ ] Helmet middleware installed
- [ ] CSP configured
- [ ] X-Powered-By header removed
- [ ] HSTS enabled (for HTTPS)
- [ ] X-Frame-Options set

### Rate Limiting
- [ ] Rate limiting implemented
- [ ] Configurable limits set
- [ ] Rate limit exceeded handler implemented
- [ ] IP-based tracking enabled

### General Security
- [ ] Request size limits set
- [ ] HTTPS enforced in production
- [ ] CORS properly configured
- [ ] Graceful shutdown implemented
- [ ] Environment-specific settings
- [ ] Logging solution implemented

---

## Common Vulnerabilities Prevented

| Vulnerability | Prevention Method |
|---------------|-------------------|
| SQL Injection | Parameterized queries + ID validation |
| XSS | Input sanitization + Content Security Policy |
| DoS/DDoS | Rate limiting + request size limits |
| Brute Force | Rate limiting on authentication endpoints |
| Information Disclosure | Proper error handling + security headers |
| CSRF | SameSite cookies + CSRF tokens (add to auth) |
| Command Injection | Whitelist validation + no eval/exec |

---

## Further Reading

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [Express Validator Guide](https://express-validator.github.io/)
- [Node.js Security Best Practices](https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html)

---

## Conclusion

These improvements significantly enhance the security posture of `app.js` by:

1. **Validating all inputs** before processing
2. **Handling errors securely** without information leakage
3. **Preventing common attacks** through security middleware
4. **Implementing defense in depth** through multiple layers

Remember, security is an ongoing process. Regularly review dependencies, update packages, and conduct security audits.

