// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet());

// Configure body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Custom error class for application-specific errors
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Input validation helper
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateId = (id) => {
  const numId = Number(id);
  return !isNaN(numId) && numId > 0 && Number.isInteger(numId);
};

const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().replace(/[<>]/g, '');
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Get users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const { limit, offset } = req.query;

    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination with validation
    if (limit !== undefined) {
      const parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        throw new AppError('Limit must be a positive integer between 1 and 100', 400);
      }
      users = users.slice(0, parsedLimit);
    }

    if (offset !== undefined) {
      const parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        throw new AppError('Offset must be a non-negative integer', 400);
      }
      users = users.slice(parsedOffset);
    }

    res.json({
      data: users,
      count: users.length,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    if (error instanceof AppError) {
      res.status(error.statusCode).json({
        error: error.message
      });
    } else {
      console.error('Unexpected error in /users:', error);
      res.status(500).json({
        error: 'Internal server error',
        message: 'An unexpected error occurred'
      });
    }
  }
});

// Get user by ID endpoint with validation
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!validateId(id)) {
      throw new AppError('Invalid user ID', 400);
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id, 10));

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json({
      data: user,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with comprehensive validation
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      throw new AppError('Name and email are required', 400);
    }

    // Validate field types
    if (typeof name !== 'string' || typeof email !== 'string') {
      throw new AppError('Name and email must be strings', 400);
    }

    // Sanitize and validate inputs
    const sanitizedName = sanitizeString(name);
    const sanitizedEmail = sanitizeString(email);

    if (sanitizedName.length === 0) {
      throw new AppError('Name cannot be empty', 400);
    }

    if (!validateEmail(sanitizedEmail)) {
      throw new AppError('Invalid email format', 400);
    }

    if (sanitizedName.length > 100) {
      throw new AppError('Name cannot exceed 100 characters', 400);
    }

    // In a real application, you would save to database here
    const newUser = {
      id: Date.now(), // Simple ID generation
      name: sanitizedName,
      email: sanitizedEmail
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

// Global error handler middleware
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use a proper logging service)
  console.error('Error:', {
