const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limiting for authentication-sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: {
    error: 'Too many authentication attempts, please try again later.',
  },
});

app.use(limiter);

// Body parser with size limits to prevent payload overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  // Log error (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak sensitive error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
  });
};

// Routes

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with validation
app.get('/users', 
  [
    // Query parameter validation
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be either asc or desc'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { limit = 10, offset = 0, sort = 'id', order = 'asc' } = req.query;

      // Mock data - in production, this would come from a database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Sanitize and validate data before sending
      const sanitizedUsers = allUsers
        .filter(user => user && typeof user === 'object')
        .map(user => ({
          id: typeof user.id === 'number' ? user.id : null,
          name: typeof user.name === 'string' ? 
            user.name.replace(/[<>]/g, '') : null, // Basic XSS prevention
          email: typeof user.email === 'string' && 
            /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email) ? 
            user.email : null,
        }))
        .filter(user => user.id !== null);

      // Apply pagination and sorting (with validation)
      const startIndex = Math.max(0, offset);
      const endIndex = Math.min(sanitizedUsers.length, startIndex + limit);
      const paginatedUsers = sanitizedUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        meta: {
          total: sanitizedUsers.length,
          limit,
          offset,
          sort,
          order,
        },
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example: User creation endpoint (demonstrates body validation)
app.post('/users',
  authLimiter,
  [
    // Body validation
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // In production, save to database with proper escaping
      const newUser = {
        id: Date.now(), // Not recommended for production - use proper ID generation
        name: name,
        email: email,
        createdAt: new Date().toISOString(),
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      next(error);
    }
  }
);

// Apply error handlers after all routes
app.use(notFoundHandler);
app.use(errorHandler);

// Log unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Log uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Start server (with environment-based configuration)
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

