app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Parse JSON with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));

// Request logging middleware (consider using winston/morgan in production)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', 
  // Validate query parameters
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('sort')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Sort must be one of: name, email, id')
      .trim(),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be asc or desc')
  ],
  validateRequest,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters, sorting, pagination based on validated query params
      let result = [...users];

      // Apply sorting
      if (req.query.sort) {
        const sortOrder = req.query.order === 'desc' ? -1 : 1;
        result.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1 * sortOrder;
          if (a[req.query.sort] > b[req.query.sort]) return 1 * sortOrder;
          return 0;
        });
      }

      // Apply pagination
      if (req.query.offset) {
        result = result.slice(parseInt(req.query.offset));
      }
      if (req.query.limit) {
        result = result.slice(0, parseInt(req.query.limit));
      }

      // Send response with consistent structure
      res.json({
        success: true,
        data: result,
        meta: {
          count: result.length,
          total: users.length
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        success: false,
        error: 'An error occurred while fetching users',
        requestId: req.id // Include request ID for tracing
      });
    }
  }
);

// Async error wrapper for route handlers
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

