#!/usr/bin/env node

/**
 * Credential Verification Script
 * Tests the validity of credentials stored in .env.test
 * No external dependencies required
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');
const net = require('net');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  gray: '\x1b[90m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function success(message) {
  log(`✓ ${message}`, 'green');
}

function error(message) {
  log(`✗ ${message}`, 'red');
}

function warning(message) {
  log(`⚠ ${message}`, 'yellow');
}

function info(message) {
  log(`ℹ ${message}`, 'blue');
}

// Parse .env.test file manually
function parseEnvFile(filePath) {
  const env = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        if (key && valueParts.length > 0) {
          env[key.trim()] = valueParts.join('=').trim();
        }
      }
    });
  } catch (err) {
    console.error(`Error reading .env file: ${err.message}`);
  }
  return env;
}

// Test 1: Validate format of DATABASE_URL
async function testDatabaseUrl(env) {
  log('\n--- Testing DATABASE_URL ---', 'blue');

  const dbUrl = env.DATABASE_URL;

  if (!dbUrl) {
    error('DATABASE_URL not set');
    return false;
  }

  info(`Database URL: ${dbUrl.replace(/:[^:]+@/, ':****@')}`);

  try {
    const url = new URL(dbUrl);

    // Check format
    if (url.protocol !== 'postgres:' && url.protocol !== 'postgresql:') {
      error('Invalid protocol, expected postgres:// or postgresql://');
      return false;
    }

    if (!url.hostname) {
      error('Missing hostname');
      return false;
    }

    if (!url.username) {
      error('Missing username');
      return false;
    }

    const port = url.port || '5432';
    info(`Testing connection to ${url.hostname}:${port}...`);

    // Attempt TCP connection
    const result = await testTcpConnection(url.hostname, parseInt(port), 3000);

    if (result) {
      success('PostgreSQL server is reachable');
      return true;
    } else {
      error('Could not connect to PostgreSQL server');
      warning('Server may be down, hostname is incorrect, or network is restricted');
      return false;
    }

  } catch (err) {
    error(`Invalid DATABASE_URL format: ${err.message}`);
    return false;
  }
}

// Test 2: Test AWS credentials
async function testAwsCredentials(env) {
  log('\n--- Testing AWS Credentials ---', 'blue');

  const accessKeyId = env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    error('AWS credentials not set');
    return false;
  }

  info(`Access Key ID: ${accessKeyId.substring(0, 8)}...`);

  // Check format: AWS access keys start with AKIA followed by 16 chars
  const accessKeyPattern = /^AKIA[A-Z0-9]{16}$/;

  if (!accessKeyPattern.test(accessKeyId)) {
    warning('AWS Access Key ID format looks unusual (expected AKIA followed by 16 alphanumeric chars)');
  } else {
    success('AWS Access Key ID format is valid');
  }

  // Check secret key format (40 chars)
  if (secretAccessKey.length !== 40) {
    warning(`AWS Secret Access Key length is ${secretAccessKey.length} (expected 40 chars)`);
  } else {
    success('AWS Secret Access Key length is valid');
  }

  // Check if credentials are canary values
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    error('Credentials contain CANARY - these are test values, not real credentials');
    return false;
  }

  info('Attempting AWS STS GetCallerIdentity...');

  const result = await testAwsSts(accessKeyId, secretAccessKey);
  return result;
}

// Test 3: Test Anthropic API key
async function testAnthropicApiKey(env) {
  log('\n--- Testing Anthropic API Key ---', 'blue');

  const apiKey = env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    error('ANTHROPIC_API_KEY not set');
    return false;
  }

  info(`API Key: ${apiKey.substring(0, 15)}...`);

  // Check format: sk-ant- followed by chars
  if (!apiKey.startsWith('sk-ant-')) {
    error('Invalid API key format (should start with sk-ant-)');
    return false;
  }

  // Check if it's a canary value
  if (apiKey.includes('CANARY')) {
    error('API key contains CANARY - this is a test value, not a real credential');
    return false;
  }

  info('Testing Anthropic API with a minimal request...');

  const result = await testAnthropicApi(apiKey);
  return result;
}

// Test 4: Test Stripe API key
async function testStripeApiKey(env) {
  log('\n--- Testing Stripe API Key ---', 'blue');

  const stripeKey = env.STRIPE_SECRET_KEY;

  if (!stripeKey) {
    error('STRIPE_SECRET_KEY not set');
    return false;
  }

  info(`Secret Key: ${stripeKey.substring(0, 10)}...`);

  // Check format
  if (stripeKey.startsWith('sk-live-')) {
    info('This is a live Stripe key (production)');
  } else if (stripeKey.startsWith('sk-test-')) {
    info('This is a test Stripe key');
  } else {
    error('Invalid Stripe key format (should start with sk-live- or sk-test-)');
    return false;
  }

  // Check if it's a canary value
  if (stripeKey.includes('CANARY')) {
    error('Stripe key contains CANARY - this is a test value, not a real credential');
    return false;
  }

  info('Testing Stripe API with a balance request...');

  const result = await testStripeApi(stripeKey);
  return result;
}

// Test 5: Test Logfire token
async function testLogfireToken(env) {
  log('\n--- Testing Logfire Token ---', 'blue');

  const token = env.LOGFIRE_TOKEN;

  if (!token) {
    error('LOGFIRE_TOKEN not set');
    return false;
  }

  info(`Token: ${token.substring(0, 15)}...`);

  // Check if it's a canary value
  if (token.includes('CANARY')) {
    error('Token contains CANARY - this is a test value, not a real credential');
    return false;
  }

  info('Logfire tokens are difficult to validate without sending actual log data');
  success('Token format appears valid (no obvious issues)');
  return true;
}

// Helper: Test TCP connection with timeout
function testTcpConnection(host, port, timeout = 5000) {
  return new Promise((resolve) => {
    const socket = net.createConnection({ host, port, timeout });

    socket.on('connect', () => {
      socket.destroy();
      resolve(true);
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve(false);
    });

    socket.on('error', () => {
      resolve(false);
    });
  });
}

